  const productFocusedCopy={
    'cua-upvc':{intro:'Danh mục uPVC gồm cửa đi và cửa sổ thuộc các dòng Asiawindow và Kömmerling. Profile, kính, gioăng, phụ kiện và kiểu mở cần đối chiếu theo mẫu cụ thể.',body:'Các kiểu mở gồm quay, trượt, hất và quay lật. Chọn theo vị trí lắp, hướng mở và khoảng thao tác; yêu cầu cách âm hoặc cách nhiệt cần đối chiếu thông số của đúng bộ cửa.',points:[['Khung uPVC gia cường','Profile dạng hộp kết hợp lõi thép bên trong, tạo bộ khung chắc chắn.'],['Gioăng và phụ kiện','Loại gioăng và phụ kiện cần được xác nhận theo dòng cửa, vị trí lắp đặt và yêu cầu vận hành.'],['Hai dòng sản phẩm','Asiawindow và Kömmerling mang đến lựa chọn đa dạng cho cửa đi và cửa sổ.'],['Nhiều kiểu mở','Chọn kiểu mở theo diện tích thao tác, hướng gió và vị trí lắp đặt.']],applications:[['Nhà phố','Cửa uPVC dùng cho cửa đi, cửa sổ và ban công; có thể chọn kiểu mở phù hợp không gian.'],['Chung cư','Cửa sổ uPVC giúp lấy sáng, thông gió và giảm tiếng ồn từ bên ngoài.'],['Biệt thự','Cửa đi và cửa sổ tạo sự kết nối giữa không gian trong nhà với sân vườn.']],faq:[['Cửa uPVC Eurowindow có những dòng nào?','Eurowindow giới thiệu cửa uPVC Asiawindow và Kömmerling, gồm các mẫu cửa đi và cửa sổ.'],['Cửa uPVC có cách âm không?','Mức độ cách âm phụ thuộc profile, loại kính, gioăng và độ kín sau lắp đặt. Cần đối chiếu thông số của bộ cửa cụ thể.'],['Cửa uPVC có những kiểu mở nào?','Các mẫu phổ biến gồm mở quay, mở trượt, mở hất và quay lật.']]},
    'cua-go':{intro:'Danh mục gồm cửa gỗ tự nhiên, gỗ công nghiệp, gỗ ghép thanh và composite. Vật liệu lõi, bề mặt hoàn thiện và vị trí lắp đặt khác nhau theo từng dòng.',body:'Cửa gỗ thường dùng trong nhà. Với cửa chính hoặc vị trí gần khu vực ẩm, cần kiểm tra vật liệu, lớp hoàn thiện và điều kiện bảo hành của mẫu được chọn.',points:[['Nhiều dòng cửa','Có thể lựa chọn cửa gỗ tự nhiên, gỗ công nghiệp, gỗ ghép thanh hoặc composite.'],['Bề mặt đa dạng','Màu sơn và vân gỗ giúp đồng bộ cửa với sàn, tủ và đồ nội thất.'],['Không gian riêng tư','Cửa gỗ tạo cảm giác ấm cúng, phù hợp cửa phòng ngủ và cửa thông phòng.'],['Kiểu dáng hài hòa','Nhiều mẫu cánh cửa phù hợp từ nội thất hiện đại đến phong cách cổ điển.']],applications:[['Cửa thông phòng','Kết nối các phòng với màu sắc và kiểu dáng đồng bộ.'],['Phòng ngủ, phòng làm việc','Tạo sự riêng tư và cảm giác ấm áp cho không gian.'],['Cửa chính','Các mẫu gỗ tự nhiên và gỗ công nghiệp làm điểm nhấn cho lối vào.']],faq:[['Cửa gỗ Eurowindow có những loại nào?','Danh mục có cửa gỗ tự nhiên, gỗ công nghiệp, gỗ ghép thanh và cửa gỗ composite.'],['Cửa gỗ phù hợp với không gian nào?','Cửa gỗ thường được dùng cho cửa chính, cửa phòng ngủ và cửa thông phòng.'],['Cửa gỗ có những lựa chọn bề mặt nào?','Tùy dòng sản phẩm, cửa có các màu sơn và vân gỗ khác nhau để phối với nội thất.']]},
    'cua-cuon':{intro:'Cửa cuốn nhôm khe thoáng EASD45 sử dụng nan mành có khe thoáng và vận hành bằng động cơ điều khiển từ xa. Thân cửa cuộn lên phía trên khi mở, giải phóng diện tích trước lối vào.',body:'Thiết kế cửa cuốn gọn, không chiếm diện tích mở cánh. Động cơ và bộ điều khiển hỗ trợ đóng mở thuận tiện trong sinh hoạt hằng ngày.',points:[['Nan nhôm khe thoáng','Khe thoáng trên nan giúp không khí lưu thông khi cửa đóng.'],['Đóng mở gọn','Thân cửa cuốn lên phía trên, giải phóng khoảng trống trước lối vào.'],['Vận hành bằng động cơ','Động cơ và bộ điều khiển giúp thao tác đóng mở thuận tiện.'],['Thiết kế mặt tiền','Kiểu nan nhôm phù hợp nhà phố, cửa hàng và gara.']],applications:[['Nhà phố','Che chắn lối vào mà vẫn giữ sự thông thoáng.'],['Cửa hàng','Mở rộng không gian mặt tiền khi cửa cuốn được kéo lên.'],['Gara','Tiết kiệm diện tích và thuận tiện khi đóng mở lối xe ra vào.']],faq:[['EASD45 là loại cửa nào?','EASD45 là cửa cuốn nhôm khe thoáng của Eurowindow.'],['Cửa cuốn khe thoáng có lợi ích gì?','Nan có khe thoáng; thân cửa cuộn lên phía trên nên không cần chừa cung mở cánh.'],['Cửa cuốn đóng mở như thế nào?','Sản phẩm sử dụng động cơ và bộ điều khiển để hỗ trợ đóng mở.']]},
    'cua-thong-minh-the-he-moi':{intro:'Danh mục cửa thông minh gồm cửa tự động, cửa sổ điều khiển từ xa và kính điện. Phương thức vận hành được xác định theo từng mẫu.',body:'Một số mẫu hỗ trợ remote, nút bấm hoặc điều khiển bằng giọng nói; cửa tự động và kính điện có phương thức vận hành riêng. Cảm biến, kết nối và tính năng an toàn cần xác nhận theo sản phẩm cụ thể.',points:[['Điều khiển tiện lợi','Một số mẫu hỗ trợ ứng dụng, điều khiển từ xa, nút bấm hoặc giọng nói.'],['Hỗ trợ kiểm soát ra vào','Phương thức điều khiển phụ thuộc mẫu và hệ phụ kiện đi kèm.'],['Cảm biến thông minh','Cảm biến hỗ trợ cửa vận hành tự động trên các sản phẩm tương thích.'],['Trải nghiệm hiện đại','Mỗi sản phẩm có cách đóng mở và yêu cầu lắp đặt riêng.']],applications:[['Nhà ở thông minh','Tăng tiện nghi cho cửa đi và cửa sổ trong sinh hoạt hằng ngày.'],['Sảnh và lối vào','Hỗ trợ đóng mở thuận tiện tại khu vực có nhiều người qua lại.'],['Văn phòng, khách sạn','Góp phần hiện đại hóa lối vào và trải nghiệm sử dụng.']],faq:[['Cửa thông minh có thể điều khiển bằng cách nào?','Tùy mẫu, cửa có thể hỗ trợ ứng dụng, điều khiển từ xa, nút bấm hoặc giọng nói.'],['Cửa thông minh có tính năng nhận diện không?','Một số giải pháp có tính năng nhận diện và kiểm soát ra vào.'],['Cửa tự động phù hợp với đâu?','Sản phẩm phù hợp nhà ở, văn phòng, khách sạn và khu vực có nhu cầu đóng mở thuận tiện.']]},
    'vach-kinh-mat-dung':{intro:'Danh mục kính gồm kính an toàn, kính cường lực, hộp kính, kính hoa văn và kính cách nhiệt, dùng cho cửa, vách ngăn hoặc mặt dựng theo thiết kế.',body:'Chọn kính theo vị trí lắp đặt, kích thước, yêu cầu an toàn, ánh sáng và mức độ riêng tư. Các chỉ tiêu cách âm, cách nhiệt hoặc kiểm soát nắng cần đối chiếu tài liệu của từng loại kính.',points:[['Đa dạng chủng loại','Kính an toàn, kính cường lực, hộp kính và kính hoa văn có cách chế tạo và mục đích sử dụng khác nhau.'],['Lấy sáng, mở rộng tầm nhìn','Kính dùng cho cửa và mặt dựng giúp không gian sáng, thoáng hơn.'],['Tăng riêng tư, trang trí','Kính hoa văn tạo điểm nhấn và giúp phân chia không gian.'],['Hỗ trợ cách âm, cách nhiệt','Một số dòng kính được thiết kế để hạn chế tiếng ồn và truyền nhiệt.']],applications:[['Mặt tiền','Vách kính tạo diện mạo hiện đại và mở rộng tầm nhìn ra bên ngoài.'],['Vách ngăn','Phân chia không gian nhưng vẫn giữ cảm giác sáng và thoáng.'],['Cửa đi, cửa sổ','Kính kết hợp với khung cửa tạo nên các mẫu cửa đa dạng.']],faq:[['Eurowindow có những loại kính nào?','Danh mục có kính an toàn, kính cường lực, kính hộp, kính hoa văn và kính cách nhiệt.'],['Kính có thể dùng ở đâu?','Kính được sử dụng cho cửa đi, cửa sổ, vách ngăn, mặt dựng và một số hạng mục nội thất.'],['Kính hộp có ưu điểm gì?','Cấu tạo nhiều lớp và khoang khí giúp hỗ trợ cách âm, cách nhiệt cho cửa và mặt dựng.']]},
    'cua-di-mo-quay':{intro:'Cửa đi mở quay có cánh mở quanh bản lề, tạo lối ra vào rộng và thao tác quen thuộc. Mẫu cửa có thể dùng một hoặc nhiều cánh.',body:'Kiểu cửa này phù hợp cửa chính, cửa ban công và lối ra sân vườn. Cửa mở quay có thể kết hợp khung nhôm, uPVC hoặc vật liệu khác tùy dòng sản phẩm.',points:[['Lối đi rộng','Cánh mở quay tạo khoảng thông hành thuận tiện.'],['Thao tác quen thuộc','Đóng mở bằng tay nắm đơn giản, dễ sử dụng.'],['Nhiều lựa chọn vật liệu','Danh mục có mẫu cửa mở quay bằng nhôm, uPVC và gỗ.']],applications:[['Cửa chính','Tạo lối vào rõ ràng và thuận tiện cho ngôi nhà.'],['Ban công','Kết nối không gian bên trong với khu vực bên ngoài.'],['Cửa thông phòng','Phù hợp những nơi có khoảng trống cho cánh cửa mở.']],faq:[['Cửa đi mở quay có ưu điểm gì?','Cửa tạo lối đi rộng, vận hành quen thuộc và phù hợp nhiều vị trí.'],['Cửa mở quay có những vật liệu nào?','Tùy bộ sưu tập, có cửa mở quay bằng nhôm, uPVC và gỗ.'],['Cửa mở quay có thể có bao nhiêu cánh?','Có các mẫu một cánh và nhiều cánh tùy dòng sản phẩm.']]},
    'cua-di-mo-truot':{intro:'Cửa đi mở trượt vận hành bằng cách trượt cánh sang bên, không cần khoảng trống để cánh quét vào trong hoặc ra ngoài.',body:'Thiết kế gọn giúp cửa trượt phù hợp ban công, phòng khách nhìn ra sân vườn và những nơi cần tiết kiệm diện tích. Nhiều cánh kính cũng giúp không gian đón sáng và kết nối với bên ngoài.',points:[['Tiết kiệm diện tích','Cánh trượt gọn theo phương ngang, không chiếm khoảng mở phía trước cửa.'],['Đón sáng','Các mẫu cửa kính mở rộng tầm nhìn và giúp ánh sáng tự nhiên vào nhà.'],['Dễ kết nối không gian','Phù hợp cửa ban công và lối ra sân vườn.']],applications:[['Ban công','Không vướng bàn ghế hoặc lối đi cạnh cửa.'],['Phòng khách nhìn ra sân','Tạo tầm nhìn thoáng và kết nối trong ngoài.'],['Nhà phố','Tận dụng diện tích ở những vị trí hẹp.']],faq:[['Cửa trượt hoạt động thế nào?','Cánh cửa di chuyển ngang trên ray để mở và đóng.'],['Cửa mở trượt có tiết kiệm diện tích không?','Có. Cánh trượt không cần khoảng trống để quay vào phòng.'],['Cửa đi trượt phù hợp vị trí nào?','Thường dùng ở ban công, phòng khách và lối ra sân vườn.']]},
    'cua-xep-truot':{intro:'Cửa xếp trượt gồm nhiều cánh liên kết, có thể xếp gọn sang một bên khi mở. Kiểu cửa này tạo khoảng mở lớn giữa các không gian.',body:'Cửa xếp trượt thường được dùng tại phòng khách, ban công và lối ra sân vườn. Khi mở, các cánh gom gọn giúp kết nối liền mạch giữa trong nhà và ngoài trời.',points:[['Mở rộng không gian','Nhiều cánh xếp gọn giúp mở rộng lối đi.'],['Kết nối trong và ngoài nhà','Phù hợp khu vực hướng ra ban công hoặc sân vườn.'],['Tạo điểm nhấn kiến trúc','Mảng cửa lớn đem lại vẻ hiện đại và thoáng đãng.']],applications:[['Phòng khách','Mở rộng không gian sinh hoạt khi tiếp khách.'],['Ban công, sân vườn','Kết nối lối đi với không gian ngoài trời.'],['Biệt thự, nhà vườn','Tạo tầm nhìn rộng và lối mở thoáng.']],faq:[['Cửa xếp trượt có thể mở rộng đến đâu?','Các cánh cửa có thể xếp gọn về một phía, tạo khoảng mở lớn.'],['Cửa xếp trượt phù hợp với nhà nào?','Sản phẩm thường dùng cho biệt thự, nhà vườn và không gian có lối ra ngoài.'],['Cửa xếp trượt khác cửa trượt thế nào?','Cửa xếp trượt gom nhiều cánh về một bên; cửa trượt thông thường có cánh chạy dọc theo ray.']]},
    'cua-so-mo-quay':{intro:'Cửa sổ mở quay có cánh mở quanh bản lề, giúp lấy gió và vệ sinh mặt ngoài thuận tiện ở những vị trí dễ tiếp cận.',body:'Mẫu cửa này có thể mở vào trong hoặc ra ngoài, thường dùng cho phòng ngủ, phòng khách và các ô cửa cần thông thoáng.',points:[['Mở thoáng','Cánh mở quay tạo khoảng thông gió rộng.'],['Dễ vệ sinh','Có thể tiếp cận bề mặt kính thuận tiện ở vị trí phù hợp.'],['Phối hợp nhiều không gian','Danh mục có cửa sổ mở quay bằng nhôm và uPVC.']],applications:[['Phòng ngủ','Lấy sáng và thông gió cho không gian nghỉ ngơi.'],['Phòng khách','Mở rộng tầm nhìn và đón khí trời.'],['Nhà phố','Bố trí tại các ô cửa có khoảng mở phù hợp.']],faq:[['Cửa sổ mở quay có ưu điểm gì?','Cửa mở thoáng, thao tác đơn giản và thuận tiện vệ sinh khi đặt ở vị trí phù hợp.'],['Cửa sổ mở quay mở theo hướng nào?','Tùy mẫu, cánh cửa có thể mở vào trong hoặc ra ngoài.'],['Cửa sổ mở quay có những vật liệu nào?','Danh mục có cửa sổ mở quay bằng nhôm và uPVC.']]},
    'cua-so-mo-hat':{intro:'Cửa sổ mở hất mở cánh ra ngoài từ cạnh dưới, giúp không khí lưu thông trong khi phần cánh phía trên che bớt mưa nhẹ.',body:'Kiểu mở hất gọn, phù hợp ô cửa cần thông gió mà không cần mở rộng toàn bộ cánh. Sản phẩm thường được dùng tại phòng ngủ, nhà bếp và khu vực phụ.',points:[['Thông gió','Cánh mở hất tạo khe thoáng để không khí lưu chuyển.'],['Che mưa nhẹ','Phần cánh phía trên có thể hạn chế mưa tạt nhẹ.'],['Gọn gàng','Cánh mở ra ngoài, phù hợp với ô cửa không cần khoảng mở lớn.']],applications:[['Phòng ngủ','Bổ sung sự thông thoáng cho không gian nghỉ ngơi.'],['Nhà bếp','Hỗ trợ lưu thông không khí.'],['Ô cửa trên cao','Có thể dùng ở vị trí cần thông gió thường xuyên.']],faq:[['Cửa sổ mở hất có thông gió được không?','Có. Cánh mở hất tạo khe thoáng để không khí lưu chuyển.'],['Cửa mở hất có che mưa không?','Cánh có thể che bớt mưa nhẹ; hiệu quả còn tùy hướng gió và thời tiết.'],['Cửa sổ mở hất phù hợp ở đâu?','Thường dùng tại phòng ngủ, nhà bếp và các ô cửa cần thông gió.']]}
  };
  Object.entries(productFocusedCopy).forEach(([slug,copy])=>Object.assign(productPageContent[slug],copy));
  Object.assign(productPageContent['cua-upvc'],{
    intro:'Cửa uPVC Eurowindow gồm cửa đi và cửa sổ thuộc các dòng Asiawindow và Kömmerling. Bộ cửa kết hợp profile, kính, gioăng, phụ kiện và kiểu mở đồng bộ theo từng dòng sản phẩm.',
    body:'Các kiểu mở gồm quay, trượt, hất và quay lật. Kiểu mở được lựa chọn theo vị trí lắp, hướng mở và khoảng thao tác. Profile, kính, gioăng, phụ kiện và độ kín khít phối hợp để hạn chế truyền âm, truyền nhiệt.',
    points:[['Khung uPVC gia cường','Profile dạng hộp kết hợp lõi thép bên trong, tạo bộ khung cửa chắc chắn.'],['Gioăng và phụ kiện','Gioăng kép phối hợp hệ phụ kiện đồng bộ, tạo độ kín khít và vận hành ổn định.'],['Hai dòng sản phẩm','Asiawindow và Kömmerling gồm các lựa chọn cửa đi và cửa sổ.'],['Nhiều kiểu mở','Các kiểu mở quay, trượt, hất và quay lật đáp ứng vị trí lắp đặt và khoảng thao tác khác nhau.']],
    applications:[['Nhà phố','Cửa uPVC dùng cho cửa đi, cửa sổ và ban công.'],['Chung cư','Cửa sổ uPVC lấy sáng, thông gió và hạn chế tiếng ồn từ bên ngoài.'],['Biệt thự','Cửa đi và cửa sổ kết nối không gian trong nhà với sân vườn.']]
  });
  function compactProductHero(title){return pageHero('Sản phẩm',title,'').replace('<section class="page-hero">','<section class="page-hero page-hero-compact">').replace('<p></p>','')}
  function displayProductName(title){return title.replace(/\bupvc\b/gi,'uPVC').replace(/\beurowindow\b/gi,'Eurowindow')}
  function productInquiryForm(options){const old='<option>Cửa đi</option><option>Cửa sổ</option><option>Vách kính & mặt dựng</option><option>Khác</option>';const choices=options.map(option=>`<option>${option}</option>`).join('');return form(true).replace(old,choices)}
  const productChildFamilies=['cua-upvc','cua-go','cua-cuon','cua-thong-minh-the-he-moi','vach-kinh-mat-dung'];
  function productChildRecords(){const records=productChildFamilies.flatMap(family=>productCatalogRows(family).map(row=>({family,row})));return [...aluminumProducts.map(item=>({family:'cua-nhom',row:[item.name,item.image,item.type,item.opening,item.system]})),...records]}
  function productChildRecord(slug){return productChildRecords().find(record=>productChildSlug(record.row[0])===slug)}
  function productChildImageExtras(record){
    const name=record.row[0];
    const image=(file,caption)=>({src:`/images/eurowindow-products/${file}`,caption});
    if(record.family==='cua-go'){
      if(name.includes('chống cháy'))return [
        image('cua-go-chong-chay-cong-trinh-eurowindow.webp','Cửa gỗ chống cháy tại công trình'),
        image('cua-go-chong-chay-cau-tao-eurowindow.webp','Cấu tạo cửa gỗ chống cháy'),
        image('cua-go-chong-chay-gioang-ngan-khoi-eurowindow.webp','Chi tiết gioăng ngăn khói')
      ];
      if(name.includes('tự nhiên'))return [image('cua-go-tu-nhien-phong-cach-sang-trong-eurowindow.webp','Không gian cửa gỗ tự nhiên'),image('cua-go-tu-nhien-cac-dong-go-eurowindow.webp','Các lựa chọn gỗ tự nhiên')];
      if(name.includes('công nghiệp'))return [image('cua-go-cong-nghiep-ket-cau-eurowindow.webp','Kết cấu cửa gỗ công nghiệp'),image('cua-go-cong-nghiep-be-mat-eurowindow.webp','Bề mặt cửa gỗ công nghiệp')];
      if(name.includes('ghép thanh'))return [image('cua-go-ghep-thanh-ket-cau-eurowindow.webp','Kết cấu cửa gỗ ghép thanh'),image('cua-go-ghep-thanh-veneer-eurowindow.webp','Bề mặt veneer gỗ tự nhiên')];
      if(name.includes('composite')||name.includes('chống cháy'))return [];
    }
    if(name.includes('Cửa cuốn'))return [image('cua-cuon-nhom-khe-thoang-easd45-khe-thoang-eurowindow.webp','Khe thoáng trên mành cửa EASD45'),image('cua-cuon-nhom-khe-thoang-easd45-van-hanh-eurowindow.webp','Cửa cuốn EASD45 vận hành êm nhẹ'),image('cua-cuon-nhom-khe-thoang-easd45-cam-bien-eurowindow.webp','Cảm biến an toàn cửa cuốn EASD45'),image('cua-cuon-nhom-khe-thoang-easd45-pccc-eurowindow.webp','Kết nối hệ thống PCCC'),image('cua-cuon-nhom-khe-thoang-easd45-dieu-khien-eurowindow.webp','Điều khiển mã số trượt')];
    if(name==='Kính điện đổi màu')return [image('kinh-dien-doi-mau-trong-mo-eurowindow.webp','Kính điện đổi màu ở trạng thái trong và mờ'),image('kinh-dien-doi-mau-ung-dung-eurowindow.webp','Ứng dụng kính điện đổi màu')];
    if(name==='Vách trượt dọc tự động')return [image('vach-truot-doc-tu-dong-thiet-ke-eurowindow.webp','Vách kính trượt dọc mở rộng tầm nhìn'),image('vach-truot-doc-tu-dong-biet-thu-eurowindow.webp','Vách trượt dọc tại công trình biệt thự'),image('vach-truot-doc-tu-dong-ve-sinh-kinh-eurowindow.webp','Thiết kế hỗ trợ vệ sinh kính')];
    if(name==='Cửa mái kính Skylight')return [image('cua-mai-kinh-skylight-lay-sang-eurowindow.webp','Cửa mái kính Skylight lấy sáng và thông gió'),image('cua-mai-kinh-skylight-dong-co-eurowindow.webp','Cửa mái kính Skylight tự động'),image('cua-mai-kinh-skylight-cong-trinh-eurowindow.webp','Mái kính Skylight tại công trình nghỉ dưỡng'),image('cua-mai-kinh-skylight-khu-nghi-duong-eurowindow.webp','Không gian mái kính tại khu nghỉ dưỡng')];
    return [];
  }
  function productChildGallery(record){const [name,image]=record.row, aluminum=record.family==='cua-nhom'?aluminumProducts.find(item=>item.name===name):null, manifestImages=aluminum?productImageManifest[aluminum.slug]||[]:[], primary=name.includes('Cửa cuốn')?'/images/eurowindow-products/cua-cuon-nhom-khe-thoang-easd45-eurowindow.webp':name==='Cửa mái kính Skylight'?'/images/eurowindow-products/cua-mai-kinh-skylight-eurowindow.webp':name==='Vách trượt dọc tự động'?'/images/eurowindow-products/vach-truot-doc-tu-dong-thiet-ke-eurowindow.webp':productCatalogImage(image), photos=manifestImages.length?manifestImages.map(src=>({src,caption:name})): [{src:primary,caption:name},...productChildImageExtras(record)];return photos.filter((item,index,all)=>item.src.startsWith('/images/')&&all.findIndex(other=>other.src===item.src)===index).slice(0,12)}
  function mergeProductChildPricing(markup){const section=markup.match(/<section class="section aluminum-pricing">[\s\S]*?<\/section>/)?.[0];if(!section)return markup;const title=section.match(/<h2 class="serif">([\s\S]*?)<\/h2>/)?.[1]||'Báo giá sản phẩm',note=section.match(/<div class="section-head">[\s\S]*?<p>([\s\S]*?)<\/p>/)?.[1]||'',detail=section.match(/<p class="detail-copy">([\s\S]*?)<\/p>/)?.[1]||'',link=section.match(/<a class="button" href="([^"]+)">([\s\S]*?)<\/a>/),card=`<div class="product-child-price"><span class="eyebrow">TƯ VẤN CHI PHÍ</span><h3>${title}</h3><p>${note}</p><p>${detail}</p>${link?`<a class="button" href="${link[1]}">${link[2]}</a>`:''}</div>`;return markup.replace(section,'').replace('</ul></aside></div></section>',`</ul>${card}</aside></div></section>`)}
  function productChildContent(record){
    const [name,image,type,opening]=record.row, family=record.family, isDoor=type==='Cửa đi', isWindow=type==='Cửa sổ';
    if(family==='cua-nhom')return {intro:`${name} là mẫu cửa nhôm kính Eurowindow dành cho ${isDoor?'lối ra vào':'lấy sáng và thông gió'}. Thiết kế ${opening.toLocaleLowerCase('vi')} kết hợp khung nhôm, kính và phụ kiện đồng bộ, mang vẻ hiện đại cho ngôi nhà.`,body:`Cửa nhôm Eurowindow có nhiều mẫu cửa đi, cửa sổ và vách kính. Kiểu ${opening.toLocaleLowerCase('vi')} giúp sử dụng thuận tiện theo từng vị trí; bề mặt kính mở rộng tầm nhìn và đón ánh sáng tự nhiên.`,points:[['Kiểu mở','Mẫu cửa '+opening.toLocaleLowerCase('vi')+' giúp thao tác thuận tiện theo vị trí sử dụng.'],['Khung nhôm và kính','Kết hợp vẻ thanh thoát của khung nhôm với bề mặt kính sáng, hiện đại.'],['Vận hành ổn định','Phụ kiện đồng bộ hỗ trợ cửa đóng mở êm và nhẹ nhàng.'],['Dễ phối kiến trúc','Có các mẫu phù hợp nhà phố, căn hộ, biệt thự và công trình thương mại.']],uses:isDoor?['Cửa chính, cửa phụ','Ban công và sân vườn','Lối đi giữa các không gian']:isWindow?['Phòng ngủ, phòng khách','Ô cửa lấy sáng, thông gió','Nhà phố và căn hộ']:['Mặt tiền công trình','Vách ngăn trong nhà','Khu vực cần mở rộng tầm nhìn'],faq:[[`Mẫu ${name} có đặc điểm gì?`,`Đây là mẫu cửa nhôm kính Eurowindow với kiểu ${opening.toLocaleLowerCase('vi')}, phù hợp không gian cần thiết kế hiện đại và sử dụng thuận tiện.`],['Cửa nhôm kính dùng được ở đâu?','Cửa được sử dụng cho cửa đi, cửa sổ, ban công, sân vườn và vách kính.'],['Cửa nhôm Eurowindow có những kiểu mở nào?','Danh mục có cửa mở quay, mở trượt, mở hất, quay lật và xếp trượt.']]};
    if(family==='cua-upvc')return {intro:`${name} là mẫu cửa uPVC Eurowindow với khung profile gia cường, kính và phụ kiện đồng bộ. Kiểu ${opening.toLocaleLowerCase('vi')} tạo cách sử dụng thuận tiện cho không gian nhà ở.`,body:'Cửa uPVC có bề mặt gọn gàng, dễ phối với nội thất hiện đại. Khung cửa kết hợp kính giúp đón sáng; gioăng và phụ kiện hỗ trợ cửa đóng mở kín khít, êm ái.',points:[['Khung uPVC gia cường','Profile dạng hộp có lõi thép bên trong, tạo khung chắc chắn.'],['Kiểu mở thuận tiện','Mẫu '+opening.toLocaleLowerCase('vi')+' phù hợp nhiều cách bố trí trong nhà.'],['Kính và phụ kiện đồng bộ','Các chi tiết phối hợp tạo nên bộ cửa hài hòa, dễ sử dụng.'],['Asiawindow và Kömmerling','Hai dòng sản phẩm uPVC của Eurowindow dành cho cửa đi và cửa sổ.']],uses:isDoor?['Ban công và cửa phụ','Lối ra sân vườn','Nhà phố, biệt thự và căn hộ']:['Phòng ngủ, phòng khách','Ô cửa cần lấy sáng, thông gió','Nhà ở hiện đại'],faq:[[`Mẫu ${name} thuộc dòng cửa nào?`,'Đây là mẫu cửa uPVC Eurowindow thuộc dòng Asiawindow hoặc Kömmerling.'],['Cửa uPVC có những kiểu mở nào?','Các mẫu cửa uPVC có kiểu mở quay, mở trượt, mở hất hoặc quay lật.'],['Cửa uPVC phù hợp với không gian nào?','Sản phẩm phù hợp nhà phố, căn hộ, biệt thự và nhiều không gian dân dụng.']]};
    if(family==='cua-go'){
      const composite=name.toLowerCase().includes('composite'),fire=name.toLowerCase().includes('chống cháy'),natural=name.toLowerCase().includes('tự nhiên'),joined=name.toLowerCase().includes('ghép thanh');
      const material=composite?'gỗ composite':fire?'gỗ chống cháy':natural?'gỗ tự nhiên':joined?'gỗ ghép thanh':'gỗ công nghiệp';
      return {intro:`${name} là dòng ${material} Eurowindow, tạo điểm nhấn ấm áp cho không gian nội thất. Màu sắc và bề mặt cửa dễ kết hợp với sàn, tủ và đồ trang trí.`,body:composite?'Cửa gỗ composite có bề mặt vân gỗ hoặc sơn, phù hợp nhiều không gian trong nhà.':fire?'Cửa gỗ chống cháy được thiết kế cho các công trình cần giải pháp cửa ngăn cháy.':'Cửa có kiểu dáng đa dạng, phù hợp làm cửa chính, cửa phòng ngủ và cửa thông phòng.',points:[['Chất liệu '+material,'Mỗi dòng gỗ có sắc thái, vân và vẻ đẹp riêng.'],['Bề mặt hoàn thiện','Màu sơn và vân gỗ giúp cửa hài hòa với phong cách nội thất.'],['Không gian sử dụng','Các mẫu cửa phù hợp phòng ngủ, phòng làm việc và lối đi trong nhà.'],['Vẻ đẹp ấm áp','Cửa gỗ đem lại cảm giác gần gũi và sang trọng cho căn phòng.']],uses:['Cửa thông phòng','Phòng ngủ, phòng làm việc','Cửa chính và nội thất nhà ở'],faq:[[`Cửa ${material} có đặc điểm gì?`,`Dòng cửa này có bề mặt và kiểu dáng riêng, phù hợp không gian nội thất.`],['Cửa gỗ Eurowindow có những loại nào?','Danh mục gồm gỗ tự nhiên, gỗ công nghiệp, gỗ ghép thanh, gỗ composite và cửa gỗ chống cháy.'],['Cửa gỗ có màu sắc nào?','Tùy dòng, cửa có các lựa chọn vân gỗ và màu hoàn thiện khác nhau.']]};
    }
    if(family==='cua-cuon')return {intro:'Cửa cuốn nhôm khe thoáng EASD45 Eurowindow sử dụng nan nhôm có khe thoáng, giúp không khí lưu thông khi cửa đóng. Thiết kế cuốn gọn mang đến sự thuận tiện cho mặt tiền.',body:'Động cơ hỗ trợ cửa đóng mở nhanh gọn trong sinh hoạt hằng ngày. Kiểu nan nhôm phù hợp những nơi cần che chắn nhưng vẫn muốn giữ sự thông thoáng.',points:[['Nan nhôm khe thoáng','Hỗ trợ lưu thông không khí ngay cả khi cửa đóng.'],['Đóng mở gọn','Thân cửa cuốn lên phía trên, không chiếm khoảng trống trước cửa.'],['Động cơ tiện lợi','Hỗ trợ đóng mở cửa nhẹ nhàng trong quá trình sử dụng.'],['Diện mạo hiện đại','Bề mặt nan nhôm phù hợp mặt tiền nhà ở và cửa hàng.']],uses:['Nhà phố, gara','Cửa hàng và mặt bằng kinh doanh','Lối vào cần sự thông thoáng'],faq:[['EASD45 là sản phẩm gì?','EASD45 là dòng cửa cuốn nhôm khe thoáng của Eurowindow.'],['Cửa cuốn khe thoáng có lợi ích gì?','Các khe trên nan hỗ trợ lưu thông không khí trong khi cửa đóng.'],['Cửa cuốn vận hành ra sao?','Cửa sử dụng động cơ để hỗ trợ thao tác đóng mở.']]};
    if(family==='cua-thong-minh-the-he-moi')return {intro:`${name} là giải pháp cửa thông minh Eurowindow, kết hợp thiết kế cửa hiện đại với các tiện ích điều khiển. Tùy mẫu, sản phẩm có thể hỗ trợ đóng mở tự động, cảm biến hoặc nhận diện.`,body:'Cửa thông minh mang đến trải nghiệm sử dụng tiện nghi cho nhà ở, văn phòng và công trình dịch vụ. Một số sản phẩm hỗ trợ điều khiển bằng ứng dụng, điều khiển từ xa, nút bấm hoặc giọng nói.',points:[['Điều khiển tiện lợi','Một số mẫu hỗ trợ ứng dụng, điều khiển từ xa, nút bấm hoặc giọng nói.'],['Hỗ trợ nhận diện','Tính năng nhận diện giúp việc ra vào thuận tiện hơn trên sản phẩm tương thích.'],['Cảm biến thông minh','Cảm biến hỗ trợ cửa vận hành tự động và an toàn hơn.'],['Trải nghiệm hiện đại','Cửa thông minh kết hợp sự tiện lợi với vẻ ngoài tinh gọn.']],uses:['Nhà ở thông minh','Sảnh, lối vào và khu vực chung','Văn phòng, khách sạn và cửa hàng'],faq:[['Cửa thông minh có thể điều khiển bằng cách nào?','Tùy mẫu, cửa có thể hỗ trợ ứng dụng, điều khiển từ xa, nút bấm hoặc giọng nói.'],['Cửa thông minh có tính năng nhận diện không?','Một số sản phẩm tích hợp tính năng nhận diện và cảm biến.'],['Cửa tự động phù hợp với đâu?','Cửa phù hợp nhà ở, văn phòng, khách sạn và những nơi có nhiều người qua lại.']]};
    const glassAct=name.includes('ACT'), laminated=name.toLowerCase().includes('an toàn'), tempered=name.toLowerCase().includes('cường lực'),patterned=name.toLowerCase().includes('hoa văn'),insulated=name.toLowerCase().includes('hộp kính');
    const glassName=name.toLocaleLowerCase('vi');
    const glassIntro=glassAct?'Kính cách nhiệt an toàn ACT Eurowindow kết hợp kính và phim cách nhiệt, hỗ trợ giảm nắng nóng và giữ mảnh kính khi va đập.':laminated?'Kính an toàn nhiều lớp liên kết bằng màng phim, giúp giữ các mảnh kính khi xảy ra va đập.':tempered?'Kính cường lực được xử lý nhiệt để tăng khả năng chịu lực, phù hợp nhiều hạng mục trong nhà và ngoài trời.':patterned?'Kính hoa văn Eurowindow tạo điểm nhấn trang trí và tăng sự riêng tư cho cửa, vách ngăn và nội thất.':insulated?'Hộp kính Eurowindow gồm nhiều lớp kính và khoang khí ở giữa, hỗ trợ cách âm, cách nhiệt cho cửa và mặt dựng.':glassName.includes('stick')?`${name} Eurowindow ghép các thanh nhôm đứng, ngang và kính thành mặt dựng cho công trình cao tầng, tạo bề mặt kiến trúc sáng và hiện đại.`:glassName.includes('spider')?`${name} Eurowindow dùng liên kết điểm để đỡ các tấm kính, phù hợp mặt tiền cần tầm nhìn rộng và hạn chế khung che.`:glassName.includes('semi-unitized')?`${name} Eurowindow kết hợp mô-đun hoàn thiện sẵn với thao tác lắp ghép tại công trình, phù hợp mặt dựng kính cần linh hoạt khi triển khai.`:glassName.includes('unitized')?`${name} Eurowindow dùng các mô-đun mặt dựng hoàn thiện sẵn để lắp ghép đồng bộ, phù hợp tòa nhà cao tầng và mặt tiền có nhịp lặp lại.`:glassName.includes('mái che')?`${name} Eurowindow tạo mái lấy sáng cho hiên, sảnh và lối vào, kết hợp mặt kính với khung đỡ để che mưa nắng.`:'Kính Eurowindow có nhiều chủng loại, kiểu bề mặt và công năng cho cửa, vách ngăn và mặt tiền.';
    return {intro:glassIntro,body:glassAct?'Lớp phim giúp hạn chế nắng gắt và tia UV, đồng thời góp phần giữ mảnh kính khi có va chạm.':laminated?'Màng phim PVB góp phần tăng độ an toàn và hỗ trợ giảm tiếng ồn.':tempered?'Kính cường lực có thể dùng cho cửa, vách, lan can và các hạng mục phù hợp.':patterned?'Các mẫu hoa văn đem lại vẻ riêng tư và trang trí cho không gian.':insulated?'Cấu tạo nhiều lớp kính giúp giảm truyền âm và nhiệt qua cửa, vách.':'Sản phẩm kính mang đến lựa chọn lấy sáng, trang trí, tăng riêng tư và hỗ trợ an toàn.',points:[['Nhiều chủng loại','Có kính an toàn, kính cường lực, kính hộp, kính hoa văn và kính cách nhiệt.'],['Lấy sáng, mở rộng tầm nhìn','Kính giúp không gian sáng và thoáng hơn.'],['An toàn và riêng tư','Tùy loại kính, bề mặt có thể hỗ trợ an toàn hoặc che tầm nhìn.'],['Điểm nhấn kiến trúc','Kính dùng cho cửa, vách ngăn và mặt dựng hiện đại.']],uses:['Cửa đi, cửa sổ','Vách ngăn và mặt dựng','Nhà ở, văn phòng và công trình thương mại'],faq:[['Eurowindow có những loại kính nào?','Danh mục có kính an toàn, cường lực, hộp kính, hoa văn và kính cách nhiệt.'],['Kính Eurowindow được dùng ở đâu?','Kính được dùng cho cửa, cửa sổ, vách ngăn, mặt dựng và nội thất.'],['Hộp kính có công dụng gì?','Hộp kính nhiều lớp hỗ trợ cách âm và cách nhiệt cho công trình.']]};
  }
  function productChildSectionDescription(record){
    const [name,,type,opening]=record.row, family=record.family, lower=name.toLocaleLowerCase('vi'), motion=(opening||'').toLocaleLowerCase('vi');
    if(family==='cua-nhom'){
      if(type==='Cửa đi'){
        const leaves=(name.match(/\d+/)||[])[0]||'Nhiều', behavior=motion.includes('xếp trượt')?`Cơ chế trượt kết hợp bản lề giúp ${leaves} cánh gom gọn về một phía, mở rộng lối đi và tạo sự liền mạch giữa phòng với ban công hoặc sân vườn.`:motion.includes('trượt')?`Các cánh trượt ngang trên ray nên không chiếm khoảng quay, thuận tiện tại cửa ban công, lối ra sân vườn và những nơi cần dành diện tích cho đồ nội thất.`:`Cánh cửa mở ${motion.includes('ngoài')?'ra ngoài':'vào trong'}, tạo lối đi thoáng và thuận tiện cho việc đóng mở hằng ngày. Khi mở rộng, cửa hỗ trợ kết nối các không gian liền kề.`;
        const use=motion.includes('trượt')||motion.includes('xếp')?'ban công, sân vườn hoặc lối đi rộng':'cửa chính, cửa phòng, ban công và lối đi phụ';
        return `${name} Eurowindow là mẫu cửa đi nhôm kính dành cho ${use}. ${behavior} Khung nhôm thanh thoát kết hợp mặt kính giúp lấy sáng, mở tầm nhìn và hài hòa với kiến trúc nhà phố, căn hộ hay biệt thự.`;
      }
      if(type==='Cửa sổ'){
        const behavior=motion.includes('hất')?'Cánh mở hất tạo khe thông gió phía trên, giúp không khí lưu chuyển và hạn chế mưa hắt trực tiếp vào phòng.':motion.includes('trượt')?'Cánh trượt ngang vận hành gọn trên ray, không vướng rèm hay đồ đạc sát ô cửa và phù hợp nơi không có chỗ mở cánh.':motion.includes('lật')?'Hai chế độ quay và lật hé giúp điều chỉnh lượng gió; kiểu mở lật giữ thông thoáng mà không cần mở rộng cánh vào phòng.':`Cánh mở ${motion.includes('ngoài')?'ra ngoài':'vào trong'}, giúp đón sáng và thông gió; hướng mở được lựa chọn theo vị trí cửa và khoảng trống quanh ô cửa.`;
        const use=motion.includes('lật')?'phòng ngủ, căn hộ và các tầng cao':'phòng khách, phòng ngủ và ô cửa cần lấy sáng';
        return `${name} Eurowindow là cửa sổ nhôm kính dành cho ${use}. ${behavior} Khung nhôm gọn kết hợp kính mở rộng tầm nhìn, đưa ánh sáng tự nhiên vào nhà và tạo diện mạo hiện đại cho mặt đứng.`;
      }
      if(lower.includes('spider'))return `${name} Eurowindow sử dụng liên kết giữ kính dạng điểm, giảm các thanh khung che khuất tầm nhìn. Bề mặt kính rộng giúp mặt tiền đón sáng và giữ cảm giác thông thoáng, phù hợp sảnh, trung tâm thương mại và công trình cần nhấn mạnh kiến trúc kính.`;
      if(lower.includes('unitized'))return `${name} Eurowindow tạo mặt dựng từ các mô-đun kính được hoàn thiện sẵn, sau đó lắp ghép đồng bộ tại công trình. Các mảng kính lớn đem lại diện mạo liền mạch cho tòa nhà cao tầng, văn phòng, trung tâm thương mại và công trình có mặt đứng lặp lại.`;
      if(lower.includes('semi-unitized'))return `${name} Eurowindow kết hợp cách lắp ghép mô-đun với thao tác hoàn thiện một phần tại công trình. Giải pháp này phù hợp mặt tiền cần sự linh hoạt khi triển khai nhưng vẫn hướng tới bề mặt kính rộng, đồng đều và hiện đại.`;
      if(lower.includes('mái che'))return `${name} Eurowindow tạo mái lấy sáng cho hiên, sảnh và lối vào, giúp khu vực bên dưới sáng thoáng mà vẫn có mái che. Bề mặt kính kết hợp khung đỡ phù hợp với kiến trúc nhà ở, khách sạn và công trình dịch vụ.`;
      return `${name} Eurowindow là hệ mặt dựng nhôm kính lắp ghép theo từng thanh tại công trình. Cách triển khai này phù hợp mặt tiền có hình khối hoặc kích thước đa dạng, tạo các mảng kính liên tục cho cao ốc, văn phòng và công trình thương mại.`;
    }
    if(family==='cua-upvc'){
      const sliding=motion.includes('trượt'), folding=motion.includes('xếp'), tilt=motion.includes('lật'), behavior=folding?'Các cánh vừa trượt vừa xếp gọn về một phía để mở rộng lối qua lại, thuận tiện khi kết nối phòng với ban công hoặc sân vườn.':sliding?'Cánh trượt ngang giúp tiết kiệm diện tích quanh cửa, đồng thời tránh vướng lối đi khi cửa mở.':motion.includes('hất')?'Cánh mở hất tạo khoảng thông gió phía trên, giúp căn phòng thoáng mà không chiếm phần diện tích sử dụng bên dưới.':tilt?'Kiểu quay lật cho phép mở cánh hoặc hé phần trên để thông gió, phù hợp khi muốn duy trì không khí lưu thông trong nhà.':`Cánh mở ${motion.includes('ngoài')?'ra ngoài':'vào trong'}, thuận tiện cho lối đi và cách bố trí nội thất.`;
      const use=type==='Cửa đi'?(folding?'lối ra sân vườn, ban công và cửa thông phòng cần khẩu độ rộng':'cửa chính, ban công và lối ra sân vườn'):(tilt?'phòng ngủ, căn hộ và vị trí cần thông gió linh hoạt':'phòng khách, phòng ngủ và các ô cửa cần lấy sáng');
      return `${name} Eurowindow là mẫu ${type==='Cửa đi'?'cửa đi':'cửa sổ'} uPVC phù hợp với ${use}. ${behavior} Bề mặt khung sáng gọn kết hợp kính tạo cảm giác thoáng cho nhà phố, căn hộ và biệt thự; thiết kế cửa hỗ trợ đóng mở kín khít, góp phần hạn chế tiếng ồn từ bên ngoài.`;
    }
    if(family==='cua-go'){
      const kind=lower.includes('composite')?'cửa gỗ composite':lower.includes('chống cháy')?'cửa gỗ chống cháy':lower.includes('tự nhiên')?'cửa gỗ tự nhiên':lower.includes('ghép thanh')?'cửa gỗ ghép thanh':'cửa gỗ công nghiệp';
      const detail=lower.includes('composite')?'Vật liệu gỗ nhựa kháng ẩm, hạn chế cong vênh và mối mọt; đây là mẫu phù hợp cho cửa phòng tắm, nhà vệ sinh và những khu vực thường có hơi ẩm. Bề mặt vân gỗ hoặc sơn giúp cửa dễ phối với nội thất.':lower.includes('chống cháy')?'Sản phẩm được thiết kế cho các vị trí cần giải pháp cửa ngăn cháy; bề mặt hoàn thiện giữ nét ấm áp của gỗ trong khi kết cấu chuyên dụng hỗ trợ ngăn lửa, khói theo yêu cầu an toàn của công trình.':lower.includes('tự nhiên')?'Gỗ tự nhiên với đường vân riêng tạo điểm nhấn sang trọng cho cửa chính, phòng khách và cửa thông phòng. Mỗi lựa chọn màu gỗ đem đến sắc thái khác nhau, từ sáng hiện đại đến trầm ấm.':lower.includes('ghép thanh')?'Các thanh gỗ đã xử lý được ghép thành cánh rồi hoàn thiện bằng lớp gỗ lạng tự nhiên. Vân gỗ giữ vẻ gần gũi của vật liệu tự nhiên, còn kết cấu ghép tạo lựa chọn ổn định cho cửa thông phòng.':'Veneer, HDF, MDF hoặc bề mặt laminate đem đến nhiều màu sắc và kiểu vân để phối cùng sàn, tủ và đồ nội thất. Dòng cửa này thường được chọn làm cửa phòng ngủ, phòng làm việc và cửa thông phòng trong nhà.';
      const use=lower.includes('composite')?'nhà vệ sinh, phòng tắm và phòng thông thường':lower.includes('chống cháy')?'hành lang, lối thoát và các khu vực được yêu cầu cửa ngăn cháy':lower.includes('tự nhiên')?'cửa chính, phòng khách và cửa thông phòng':'cửa phòng ngủ, phòng làm việc và cửa thông phòng';
      return `${name} Eurowindow thuộc dòng ${kind}, phù hợp với ${use}. ${detail} Kiểu dáng và sắc thái bề mặt giúp cửa gỗ hòa hợp với phong cách nội thất, từ không gian hiện đại đến thiết kế thiên về vẻ đẹp tự nhiên.`;
    }
    if(family==='cua-cuon')return 'Cửa cuốn nhôm khe thoáng EASD45 Eurowindow sử dụng nan nhôm có khe lấy gió, giúp không khí tiếp tục lưu thông khi cửa đóng. Khi mở, thân cửa cuộn gọn phía trên nên không chiếm khoảng sân hoặc vỉa hè trước lối vào. Mẫu cửa cuốn này phù hợp nhà phố, gara và cửa hàng cần kết hợp che chắn với sự thông thoáng cho mặt tiền.';
    if(family==='cua-thong-minh-the-he-moi'){
      const detail=lower.includes('slim')?'Khung nhôm thanh mảnh và ray treo tạo cảm giác nhẹ, giúp nối liền phòng khách với bếp hoặc phân chia không gian mà không làm mất tầm nhìn.':lower.includes('rèm')?'Rèm nằm gọn giữa hai lớp kính, hạn chế bám bụi và cho phép điều chỉnh ánh sáng, tầm nhìn riêng tư ngay trên bộ cửa.':lower.includes('kính điện')?'Kính điện tử dùng phim PDLC để chuyển từ trong suốt sang mờ đục bằng thao tác điều khiển, giúp đổi giữa tầm nhìn mở và sự riêng tư mà không cần rèm che.':lower.includes('bản lề sàn')?'Cửa mở tự động qua bộ truyền động bản lề sàn, hỗ trợ lưu thông tại sảnh và lối vào có nhiều người qua lại.':lower.includes('gấp trượt')?'Các cánh chuyển động theo phương đứng và gom về một phía; khi mở, bộ cửa còn tạo mái che, mở rộng kết nối với không gian ngoài trời.':lower.includes('giọng nói')?'Cửa sổ nhận lệnh tiếng Việt và hỗ trợ điều khiển qua giọng nói, điện thoại, remote hoặc nút bấm; thuận tiện ở vị trí cao hay khi cần thao tác rảnh tay.':lower.includes('vách trượt')?'Các tấm kính trượt theo phương đứng, cho phép chuyển đổi giữa ban công mở đón gió và không gian khép kín; thiết kế hướng đến tầm nhìn rộng và dễ tiếp cận mặt kính từ bên trong.':lower.includes('đẩy ngang')?'Cánh trượt song song giúp điều chỉnh độ mở để lấy gió mà không cần thao tác trực tiếp tại cánh; các nút điều khiển có thể dừng cửa ở vị trí mong muốn.':lower.includes('skylight')?'Cửa mái kính đưa ánh sáng tự nhiên từ mái vào sâu trong nhà; cơ chế tự động và cảm biến hỗ trợ đóng mở theo điều kiện thời tiết.':lower.includes('cửa sổ')?'Cửa sổ tự động hỗ trợ đóng mở bằng điều khiển từ xa hoặc nút bấm, thuận tiện với ô cửa cao và những nơi thao tác bằng tay khó khăn.':'Cửa trượt tự động mở ngang khi có người đến gần rồi khép lại sau khi đi qua, tạo lối vào thuận tiện cho sảnh và khu vực có lưu lượng người qua lại.';
      const use=lower.includes('kính điện')?'phòng họp, phòng tắm, văn phòng và không gian cần thay đổi độ riêng tư':lower.includes('skylight')?'giếng trời, mái nhà và khu vực cần bổ sung ánh sáng tự nhiên':lower.includes('cửa sổ')?'nhà ở, căn hộ và các vị trí cửa cao':lower.includes('vách trượt')?'ban công, nhà hàng, khách sạn và mặt tiền công trình':lower.includes('cửa trượt tự động')||lower.includes('bản lề sàn')?'sảnh văn phòng, khách sạn, trung tâm thương mại và cơ sở dịch vụ':'không gian nhà ở, văn phòng và khu vực cần phân chia linh hoạt';
      return `${name} Eurowindow là sản phẩm thuộc dòng cửa thông minh thế hệ mới, phù hợp với ${use}. ${detail} Tùy sản phẩm, thao tác điều khiển được thực hiện bằng cảm biến, remote, nút bấm, ứng dụng hoặc giọng nói, đem đến trải nghiệm đóng mở thuận tiện và đồng bộ với kiến trúc hiện đại.`;
    }
    const detail=lower.includes('kính cường lực')?'Kính được xử lý nhiệt để tăng độ bền cơ học; khi vỡ, kính tạo thành các hạt nhỏ thay vì mảnh sắc dài. Sản phẩm phù hợp cửa, vách ngăn, lan can và các hạng mục nội thất.':lower.includes('hộp kính')?'Các lớp kính được ghép thành hộp với khoang khí ở giữa, giúp hạn chế truyền nhiệt và tiếng ồn qua cửa hoặc mặt dựng. Khổ kính lớn phù hợp những không gian cần mở rộng tầm nhìn.':lower.includes('an toàn')?'Các lớp kính liên kết với nhau bằng màng phim, giúp giữ mảnh kính khi bị nứt vỡ. Đây là lựa chọn cho cửa, mái kính và vách ở những vị trí cần tăng mức độ an toàn.':lower.includes('act')?'Cấu tạo kính ACT hướng đến việc hạn chế sức nóng và tia nắng truyền qua ô cửa, đồng thời giữ các mảnh kính khi xảy ra va chạm. Sản phẩm phù hợp mặt tiền hoặc khu vực đón nắng nhiều.':lower.includes('hoa văn')?'Hoa văn trên kính tạo điểm nhấn trang trí và giảm tầm nhìn xuyên qua, phù hợp cửa, vách ngăn, phòng tắm và các không gian cần sự kín đáo.':lower.includes('mái che')?'Mái kính che mưa nắng cho hiên, sảnh hoặc lối vào nhưng vẫn cho ánh sáng tự nhiên đi qua, giữ khu vực bên dưới sáng thoáng.':lower.includes('vách')?'Các tấm kính phân chia khu vực sử dụng nhưng vẫn giữ sự kết nối bằng ánh sáng và tầm nhìn, phù hợp văn phòng, sảnh và mặt tiền.':'Kính Eurowindow được lựa chọn cho cửa đi, cửa sổ, vách ngăn và mặt dựng để lấy sáng, mở rộng tầm nhìn hoặc hoàn thiện kiến trúc.';
    const use=lower.includes('mái che')?'mái hiên và lối vào':lower.includes('hoa văn')?'cửa, vách ngăn và nội thất':lower.includes('vách')?'mặt tiền, sảnh và không gian văn phòng':'cửa, vách ngăn và mặt dựng công trình';
    return `${name} Eurowindow là giải pháp kính kiến trúc dành cho ${use}. ${detail} Sản phẩm giúp không gian sáng và hiện đại; lựa chọn kính phù hợp sẽ phụ thuộc vị trí lắp đặt và mục đích sử dụng của công trình.`;
  }
  function productChildStorySections(record){
    const [name,,type,opening]=record.row, family=record.family, content=productChildContent(record), lower=name.toLocaleLowerCase('vi');
    return productChildGallery(record).slice(0,3).map((photo,index)=>{
      const caption=(photo.caption||name).toLocaleLowerCase('vi');
      let heading,body;
      if(index===0){
        const movement=(opening||'').toLocaleLowerCase('vi').replace(/^mở\s+/,'');
        heading=family==='cua-nhom'&&type==='Cửa đi'?(movement.includes('quay')?`Mở ${movement}, linh hoạt cho lối đi`:`${name}, mở rộng không gian sử dụng`):family==='cua-nhom'?`${type} nhôm kính ${opening.toLocaleLowerCase('vi')}, đón sáng và thông gió`:family==='cua-upvc'?`${type} uPVC ${opening.toLocaleLowerCase('vi')}, gọn đẹp cho nhà ở`:family==='cua-go'?`${name}, hoàn thiện vẻ đẹp ấm áp cho nội thất`:family==='cua-cuon'?'Cửa cuốn nhôm khe thoáng cho mặt tiền':'Giải pháp '+name.toLocaleLowerCase('vi')+' cho công trình hiện đại';
        body=productChildSectionDescription(record);
      }else if(caption.includes('kết cấu')||caption.includes('cấu tạo')){
        heading='Kết cấu sản phẩm được thể hiện rõ qua từng chi tiết';
        body=content.points[0]?.[1]||`Hình ảnh giúp bạn tham khảo các chi tiết của ${name.toLocaleLowerCase('vi')}.`;
      }else if(caption.includes('bề mặt')||caption.includes('veneer')||caption.includes('màu')){
        heading='Bề mặt hoàn thiện hài hòa với không gian';
        body=content.points[1]?.[1]||`Bề mặt ${name.toLocaleLowerCase('vi')} tạo điểm nhấn cho thiết kế nội thất.`;
      }else if(caption.includes('công trình')||caption.includes('biệt thự')||caption.includes('ứng dụng')||caption.includes('nghỉ dưỡng')){
        heading=`${name} trong không gian công trình thực tế`;
        body=`Hình ảnh minh họa cách ${name.toLocaleLowerCase('vi')} kết nối với kiến trúc và không gian sử dụng xung quanh.`;
      }else{
        heading=photo.caption||`Chi tiết ${name.toLocaleLowerCase('vi')}`;
        body=content.points[Math.min(index,content.points.length-1)]?.[1]||`Một góc nhìn thực tế về ${name.toLocaleLowerCase('vi')} trong quá trình sử dụng.`;
      }
      return {heading,body,image:photo.src,caption:photo.caption||name};
    });
  }
  function productChildDetailPage(slug){
    const record=productChildRecord(slug);if(!record)return notFound();
    const [name,image,type,configuration,variant]=record.row, content={...productChildContent(record),storySections:productChildStorySections(record)}, siblingRows=productChildRecords().filter(other=>other.family===record.family&&other.row[0]!==name), gallerySlides=productChildGallery(record);
    const faq=content.faq.map(([q,a])=>`<article class="aluminum-faq-item"><h3>${q}</h3><p>${a}</p></article>`).join(''), points=content.points.map(([h,p])=>`<article class="product-guide-point"><h3>${h}</h3><p>${p}</p></article>`).join(''), uses=content.uses.map(item=>`<li>${item}</li>`).join('');
    const gallery=gallerySlides, storyMarkup=content.storySections.map(item=>`<article class="product-child-story"><h3>${item.heading}</h3><p>${item.body}</p>${item.image?`<figure><img loading="lazy" src="${item.image}" alt="${item.caption||name} Eurowindow"><figcaption>${item.caption||name}</figcaption></figure>`:''}</article>`).join(''), galleryMarkup=gallery.map((item,i)=>`<button type="button" class="gallery-slide ${i===0?'active':''}" data-gallery-slide="${i}" aria-label="Xem ${item.caption}, ảnh ${i+1}"><img loading="lazy" src="${item.src}" alt="${item.caption} Eurowindow" onerror="this.closest('.gallery-slide').classList.add('image-unavailable')"><span class="gallery-caption">${item.caption} · ${String(i+1).padStart(2,'0')} / ${String(gallery.length).padStart(2,'0')}</span></button>`).join('');
    const parentTitle=record.family==='cua-nhom'?'Cửa nhôm Eurowindow':productPageContent[record.family]?.title||'Sản phẩm Eurowindow', quote=`/bao-gia?san-pham=${encodeURIComponent(name)}`;
    return `${compactProductHero(name)}<section class="section product-child-hero"><div class="wrap"><nav class="product-breadcrumb" aria-label="Breadcrumb"><a href="/">Trang chủ</a><span>/</span><a href="/san-pham">Sản phẩm</a><span>/</span><a href="/san-pham/${record.family}/">${parentTitle}</a><span>/</span><span>${name}</span></nav><div class="detail-grid"><div class="detail-gallery" data-gallery><div class="gallery-stage">${galleryMarkup}</div><div class="gallery-controls"><button type="button" data-gallery-prev aria-label="Ảnh trước">&larr;</button><span class="gallery-counter" data-gallery-counter>01 / ${String(gallery.length).padStart(2,'0')}</span><button type="button" data-gallery-next aria-label="Ảnh tiếp theo">&rarr;</button></div></div><div class="detail-info"><span class="detail-label">${type} · Sản phẩm Eurowindow</span><h2 class="product-child-title">${name} Eurowindow</h2><div class="detail-copy"><p>${content.intro}</p><p>${content.body}</p></div><a class="button" href="${quote}">Nhận tư vấn và báo giá <span class="arrow">&nearr;</span></a></div></div></div></section><section class="section product-child-information"><div class="wrap product-child-information-grid"><div><span class="eyebrow">THÔNG TIN SẢN PHẨM</span><h2 class="serif">Giới thiệu ${name}</h2><div class="product-child-story-list">${storyMarkup}</div></div><aside class="product-child-uses"><span class="eyebrow">GỢI Ý ỨNG DỤNG</span><h2 class="serif">Phù hợp với</h2><ul>${uses}</ul></aside></div></section><section class="section aluminum-pricing"><div class="wrap"><div class="section-head"><div><span class="eyebrow">THÔNG TIN SẢN PHẨM</span><h2 class="serif">Báo giá ${name}</h2></div><p>Giá bán thay đổi tùy dòng sản phẩm và thời điểm.</p></div><p class="detail-copy">Liên hệ Eurowindow để nhận thông tin giá bán và ưu đãi mới nhất cho sản phẩm này.</p><a class="button" href="${quote}">Yêu cầu báo giá <span class="arrow">&nearr;</span></a></div></section><section class="section aluminum-faq"><div class="wrap"><div class="section-head"><div><span class="eyebrow">CÂU HỎI THƯỜNG GẶP</span><h2 class="serif">Giải đáp về ${name}</h2></div></div><div class="aluminum-faq-list">${faq}</div></div></section>${siblingRows.length?`<section class="section product-child-related"><div class="wrap"><div class="section-head"><div><span class="eyebrow">CÙNG DÒNG SẢN PHẨM</span><h2 class="serif">Mẫu cửa liên quan</h2></div><a class="text-link" href="/san-pham/${record.family}/">Xem danh mục ↗</a></div><div class="door-catalog-grid">${siblingRows.slice(0,3).map(other=>productFamilyCard(other.row)).join('')}</div></div></section>`:''}<section class="quote-band"><div class="wrap quote-grid"><div><span class="eyebrow">TƯ VẤN SẢN PHẨM</span><h2 class="serif">Chọn đúng mẫu<br><span class="gold">cho công trình của bạn</span></h2><p>Liên hệ với Eurowindow để được giới thiệu mẫu mã và dòng sản phẩm phù hợp.</p></div>${productInquiryForm([name])}</div></section>`;
  }
  function productOverviewSection(content,slug){
    const row=productCatalogRows(slug)[0];
    if(!row)return '';
    const image=productCatalogImage(row[1]);
    return `<section class="aluminum-overview product-overview"><div class="wrap aluminum-overview-grid"><div class="aluminum-overview-image"><img loading="lazy" src="${image}" alt="${row[0]}" onerror="this.onerror=null;this.src='https://storage.sudospaces.com/eurowindow/2026/07/san-pham-kinh-cua-eurowindow-dam-bao-do-an-toan-phu-hop-voi-nhieu-hang-muc-cong-trinh.jpg.webp'"></div><div class="aluminum-overview-copy"><span class="eyebrow">LỰA CHỌN GIẢI PHÁP</span><h2>${displayProductName(content.title)} cho công trình của bạn</h2><p>${content.intro}</p><p>${content.body}</p></div></div></section>`;
  }
  function productGuideLayout(title,points,applications,rows,intro=[]){
    const images=[...new Map(rows.map(row=>[row[1],row])).values()].slice(0,3);
    const gallery=images.length?`<div class="product-guide-gallery product-guide-gallery-count-${images.length}">${images.map(row=>`<figure class="product-guide-gallery-item"><img loading="lazy" src="${productCatalogImage(row[1])}" alt="${row[0]}" onerror="this.onerror=null;this.src='https://storage.sudospaces.com/eurowindow/2026/07/san-pham-kinh-cua-eurowindow-dam-bao-do-an-toan-phu-hop-voi-nhieu-hang-muc-cong-trinh.jpg.webp'"><figcaption>${row[0]}</figcaption></figure>`).join('')}</div>`:'';
    const pointCards=points.map(([heading,text])=>`<article class="product-guide-point"><h3>${heading}</h3><p>${text}</p></article>`).join('');
    const applicationRows=applications.map(([heading,text])=>`<article class="product-guide-application"><span class="product-guide-application-mark" aria-hidden="true"></span><div><h3>${heading}</h3><p>${text}</p></div></article>`).join('');
    const introCopy=intro.map(text=>`<p>${text}</p>`).join('');
    const cleanTitle=displayProductName(title);
    const heading=/^Cửa\s/.test(cleanTitle)?`Cửa ${cleanTitle.replace(/^Cửa\s+/,'')} phù hợp với công trình`:`${cleanTitle} phù hợp với công trình`;
    return `<section class="section product-guide"><div class="wrap"><div class="section-head"><div><span class="eyebrow">THÔNG TIN SẢN PHẨM</span><h2 class="serif">${heading}</h2></div></div><div class="product-guide-layout">${gallery}<div class="product-guide-copy">${introCopy}<div class="product-guide-topic"><span class="product-guide-label">TIÊU CHÍ CHỌN</span><div class="product-guide-point-grid">${pointCards}</div></div><div class="product-guide-topic"><span class="product-guide-label">THEO KHÔNG GIAN</span><div class="product-guide-application-list">${applicationRows}</div></div></div></div></div></section>`;
  }
  function productGuideSections(content,slug){
    if(slug==='cua-upvc'){
      const illustration=(filename,alt)=>`<figure class="aluminum-editorial-figure"><img src="/images/cua-upvc/${encodeURIComponent(filename)}" alt="${alt}" loading="lazy" decoding="async"></figure>`;
      return `<section class="section aluminum-editorial"><div class="wrap"><article class="aluminum-editorial-content"><p>Cửa uPVC Eurowindow gồm cửa sổ, cửa đi và vách ngăn, phù hợp với khách sạn, biệt thự, chung cư và căn hộ. Bộ cửa kết hợp thanh profile uPVC dạng hộp có lõi thép gia cường, phụ kiện đồng bộ gồm chốt đa điểm, bản lề 3D và khóa chuyên dụng, gioăng kép cùng hộp kính bơm khí trơ. Các thành phần này tạo độ kín khít và hạn chế truyền âm, truyền nhiệt.</p><p>Vật liệu uPVC không bị oxy hóa hoặc ố vàng dưới tác động của bức xạ mặt trời. Cấu tạo cửa hỗ trợ cách âm, cách nhiệt, tiết kiệm điện năng và giảm chi phí bảo dưỡng, sửa chữa trong quá trình sử dụng.</p><h2>1. Tính ưu việt của cửa uPVC Eurowindow</h2><h3>1.1. Cách âm và cách nhiệt</h3><p>Khung profile, hộp kính và gioăng phối hợp để hạn chế âm thanh và nhiệt truyền qua bộ cửa. Trong ví dụ phòng nằm gần trục giao thông, tiếng ồn bên ngoài ở mức 85 dB, cửa sổ uPVC đưa mức âm thanh trong phòng xuống khoảng 40–45 dB.</p><p>Tiếng lật sách ở mức khoảng 20 dB; cuộc trò chuyện bình thường khoảng 50 dB; âm thanh trên đường giao thông khoảng 85–95 dB.</p><p>Cửa uPVC Eurowindow có khả năng cách nhiệt cao gấp 2–4 lần so với các loại cửa thông thường, góp phần giảm điện năng dùng để làm mát và sưởi ấm căn phòng.</p>${illustration('Cua-di-uPVC-mo-quay-6-canh.jpg','Cửa đi uPVC 6 cánh tại không gian nhà ở')}${illustration('cua-eurowindow- (130).JPG','Cửa uPVC lắp đặt tại công trình nhà ở')}<h3>1.2. Sử dụng ổn định, giảm chi phí bảo dưỡng</h3><p>Cửa uPVC có chi phí đầu tư ban đầu cao hơn một số loại cửa thông thường. Trong quá trình sử dụng, cửa hạn chế truyền nhiệt, giảm điện năng làm mát hoặc sưởi ấm và không đòi hỏi sơn sửa, tu bổ định kỳ. Mức tiết kiệm điện năng cùng chi phí bảo dưỡng, sửa chữa tạo hiệu quả kinh tế lâu dài; khoản đầu tư ban đầu được khấu hao sau vài năm sử dụng.</p><p>Phụ kiện kim khí đồng bộ giúp cánh cửa đóng khít và vận hành ổn định. Khung cửa giữ màu sắc, hạn chế cong vênh và co giãn trong điều kiện sử dụng.</p>${illustration('Cua-di-uPVC-mo-truot-4-canh.jpg','Cửa đi uPVC mở trượt 4 cánh')}<h3>1.3. Độ ổn định của khung cửa</h3><p>Profile uPVC dạng hộp kết hợp lõi thép gia cường giữ kết cấu bộ cửa ổn định. Khuôn và cánh cửa ăn khớp, duy trì độ kín trong quá trình sử dụng, hạn chế cong vênh và co ngót trước điều kiện khí hậu nhiệt đới.</p>${illustration('Cua-di-uPVC-mo-quay-4-canh.jpg','Cửa uPVC mở quay nhiều cánh tại công trình')}${illustration('cua-eurowindow- (134).JPG','Cửa đi uPVC tại lối vào nhà ở')}<h3>1.4. Độ bền trong khí hậu nóng ẩm</h3><p>Vật liệu uPVC không bị oxy hóa, lão hóa hay ố vàng dưới bức xạ mặt trời và trong điều kiện khí hậu nóng ẩm, mưa nhiều. Các chất phụ gia và chất ổn định trong công thức phối liệu giúp vật liệu thích ứng với nhiệt độ và độ ẩm cao. uPVC được sử dụng tại nhiều quốc gia châu Á, trong đó có Trung Quốc, Singapore, Malaysia và Thái Lan.</p>${illustration('cua-eurowindow- (132).JPG','Cửa đi uPVC tại mặt tiền công trình')}${illustration('Cua-so-uPVC-mo-quay-lat.jpg','Cửa sổ uPVC mở quay lật')}<h3>1.5. Đặc tính của vật liệu khi tiếp xúc với lửa</h3><p>Thanh profile uPVC được sản xuất từ polymer và phụ gia chống cháy. Ở mức nhiệt gần 100°C từ đèn khò, thanh uPVC biến dạng nhưng không bén cháy; đặc tính này hạn chế ngọn lửa lan truyền qua cửa.</p>${illustration('Cua-di-uPVC-mo-quay-2-canh1.jpg','Cửa đi uPVC mở quay tại khu vực phòng ăn')}<h2>2. Cấu tạo các bộ phận cửa uPVC</h2><h3>2.1. Thanh profile uPVC</h3><p>Thanh profile có cấu trúc dạng hộp, chia thành nhiều khoang và lắp lõi thép gia cường. Các khoang hỗ trợ cách âm, cách nhiệt; lõi thép tăng khả năng chịu lực cho bộ cửa.</p><p>uPVC là Polyvinyl Chloride cứng. Acrylic Polymers tăng độ bền và khả năng chịu va đập; chất ổn định hỗ trợ vật liệu trước tác động của nhiệt và tia cực tím; sáp sử dụng trong quá trình chế biến tạo bề mặt profile bóng, đẹp.</p><p>Eurowindow sử dụng thanh profile uPVC Kömmerling thuộc tập đoàn profine của Đức. Kömmerling có hơn 100 năm hoạt động trong lĩnh vực profile và là nhà sản xuất, cung cấp profile hàng đầu thế giới. Eurowindow là nhà cung cấp độc quyền profile Kömmerling tại Việt Nam.</p>${illustration('cua-eurowindow- (133).JPG','Cửa đi uPVC khung trắng tại công trình')}${illustration('cua-eurowindow- (152).JPG','Bộ cửa uPVC mở rộng tại công trình nhà ở')}<h3>2.2. Hệ phụ kiện kim khí</h3><p>Hệ phụ kiện cửa uPVC Eurowindow gồm chốt đa điểm, bản lề 3D và khóa chuyên dụng. Eurowindow sử dụng phụ kiện từ các hãng của Đức và phụ kiện do doanh nghiệp nghiên cứu, chế tạo. Bộ phụ kiện đồng bộ tăng độ an toàn và độ chính xác khi đóng mở.</p><p>Các kiểu mở gồm mở quay vào trong, mở quay ra ngoài, mở hất ra ngoài, mở quay lật vào trong, mở trượt và mở song song. Bản lề 3D điều chỉnh theo ba chiều, được bắt trực tiếp vào lõi thép gia cường trong thanh profile bằng vít chuyên dụng.</p>${illustration('Cua-so-uPVC-mo-quay-2-canh.jpg','Cửa sổ uPVC mở quay hai cánh')}${illustration('Cua-so-uPVC-mo-quay-lat1.jpg','Cửa sổ uPVC mở quay lật trong không gian nội thất')}</article></div></section>`;
    }
    if(slug==='cua-go'){
      const illustration=(filename,alt,folder='cua-go')=>`<figure class="aluminum-editorial-figure"><img src="/images/${folder}/${filename}" alt="${alt}" loading="lazy" decoding="async"></figure>`;
      return `<section class="section aluminum-editorial"><div class="wrap"><article class="aluminum-editorial-content"><p>Cửa gỗ Eurowindow gồm các dòng cửa gỗ tự nhiên, gỗ công nghiệp, gỗ ghép thanh, composite và cửa gỗ chống cháy. Cửa gỗ được sử dụng cho cửa chính, cửa thông phòng, phòng ngủ và nhiều vị trí trong công trình. Vật liệu và bề mặt hoàn thiện tạo sắc thái ấm áp, đồng thời kết hợp với nhiều phong cách kiến trúc. Các dòng cửa có kiểu dáng, kích thước và lựa chọn vật liệu đa dạng, đáp ứng những nhu cầu khác nhau về thẩm mỹ, độ bền và ngân sách.</p>${illustration('cua-go-hai-canh-noi-that-eurowindow.jpg','Cua go hai canh trong khong gian noi that')}<h2>1. Các dòng cửa gỗ Eurowindow</h2><h3>1.1. Cửa gỗ tự nhiên Eurowindow</h3><p>Cửa gỗ tự nhiên Eurowindow được sản xuất từ gỗ tự nhiên nguyên tấm đã qua công nghệ xử lý biến tính. Quy trình xử lý giúp vật liệu ổn định hơn, hạn chế cong vênh và co ngót trong điều kiện khí hậu Việt Nam. Cửa được gia công trên dây chuyền máy móc đồng bộ và hoàn thiện bằng dây chuyền sơn công nghiệp tự động.</p>${illustration('cua-di-go-van-go-dam-eurowindow.jpg','Cua di go van go sam')}<h3>1.2. Cửa gỗ công nghiệp Eurowindow</h3><p>Cửa gỗ công nghiệp Eurowindow có các lựa chọn bề mặt phủ veneer gỗ tự nhiên cao cấp và laminate. Bề mặt hoàn thiện tạo màu sắc, vân gỗ riêng cho từng thiết kế và phối hợp với nội thất công trình.</p>${illustration('cua-go-pano-trang-eurowindow.jpg','Cua go pano mau trang')}<h3>1.3. Cửa gỗ ghép thanh Eurowindow</h3><p>Cửa gỗ ghép thanh Eurowindow sử dụng gỗ rừng trồng đã qua xử lý, ghép thành kết cấu ổn định và phủ bề mặt bằng lớp gỗ lạng tự nhiên. Phần gỗ ghép được xử lý biến tính trước khi đưa vào sản xuất, giúp tăng độ ổn định, độ bền và hạn chế biến dạng khi chịu tác động của điều kiện khí hậu tại Việt Nam.</p><p>Lớp gỗ lạng tự nhiên được dán lên bề mặt bằng máy ép chân không và keo chuyên dụng theo tiêu chuẩn châu Âu. Cửa được hoàn thiện bằng dây chuyền sơn công nghiệp tự động để bảo vệ bề mặt và tạo độ đồng đều.</p>${illustration('cua-di-go-van-sang-eurowindow.jpg','Cua di go van sang')}<h3>1.4. Cửa gỗ composite Eurowindow</h3><p>Cửa gỗ composite Eurowindow kết hợp bột gỗ nghiền mịn, hạt nhựa PVC và phụ gia như bột đá. Hỗn hợp được gia nhiệt, đùn ép thành profile và định hình theo yêu cầu sản xuất. Cấu trúc polymer bao bọc thành phần gỗ, tạo khả năng kháng nước cao và hạn chế hơi ẩm xâm nhập.</p><p>Cánh cửa và khuôn đúc nguyên khối có độ dày cánh khoảng 40 mm. Profile dạng khoang rỗng kết hợp hệ gioăng kép tạo độ ổn định và kín khít, đồng thời hỗ trợ cách âm, cách nhiệt.</p>${illustration('cua-go-phong-tam-eurowindow.jpg','Cua go tai khu vuc phong tam')}<h3>1.5. Cửa gỗ chống cháy Eurowindow</h3><p>Cửa gỗ chống cháy Eurowindow có cấu tạo gồm khung xương gỗ tự nhiên, tấm khoáng Calcium Silicate, bông thủy tinh hoặc Rockwool, gioăng chống cháy và lớp gỗ lạng tự nhiên phủ sơn PU. Tấm Calcium Silicate có đặc tính cách nhiệt, không độc, không mùi; bông khoáng hỗ trợ cách âm và cách nhiệt cho kết cấu cửa. Cấp chịu lửa và cấu tạo cụ thể được lựa chọn theo yêu cầu an toàn cháy của công trình.</p>${illustration('cua-go-can-ho-eurowindow.jpg','Cua go tai loi vao can ho')}<h2>2. Cấu tạo cơ bản của cửa gỗ</h2><p>Một bộ cửa gỗ gồm cánh cửa, khuôn cửa, bề mặt hoàn thiện và phụ kiện.</p><p><strong>Cánh cửa:</strong> Tạo diện mạo chính của bộ cửa; vật liệu gồm gỗ nguyên tấm, gỗ ghép thanh, lõi MDF/HDF, composite hoặc kết cấu nhiều lớp theo từng dòng.</p><p><strong>Khuôn cửa:</strong> Liên kết cánh cửa với tường và tạo điểm tựa chắc chắn, ổn định khi đóng mở.</p><p><strong>Bề mặt hoàn thiện:</strong> Gồm sơn PU, veneer gỗ tự nhiên, laminate, melamine, film vân gỗ hoặc lớp phủ chuyên dụng để tạo thẩm mỹ và bảo vệ vật liệu.</p><p><strong>Phụ kiện:</strong> Bản lề, khóa, tay nắm, gioăng và chốt cửa hỗ trợ thao tác đóng mở, độ kín khít và độ bền sử dụng.</p>${illustration('cua-di-go-mo-quay-eurowindow.jpg','Cua go mo quay trong nha o')}<h2>3. Các loại cửa gỗ phổ biến hiện nay</h2><p>Cửa gỗ được phân loại theo vật liệu cấu tạo và yêu cầu sử dụng của công trình. Những dòng phổ biến gồm cửa gỗ tự nhiên, cửa gỗ công nghiệp, cửa gỗ ghép thanh, cửa gỗ composite và cửa gỗ chống cháy.</p>${illustration('cua-go-tu-nhien-eurowindow.webp','Cua go tu nhien Eurowindow','eurowindow-products')}<h3>3.1. Cửa gỗ tự nhiên</h3><p>Cửa gỗ tự nhiên sử dụng gỗ nguyên tấm hoặc gỗ tự nhiên đã qua xử lý để sản xuất cánh cửa. Vân gỗ và màu sắc tự nhiên tạo điểm nhấn cho cửa chính, biệt thự và không gian nội thất.</p><p><strong>Gỗ Sồi</strong> có gam màu sáng và vân rõ, phù hợp với phong cách hiện đại, Scandinavian và tối giản. <strong>Gỗ Lim</strong> có độ cứng cao, màu trầm, thường được dùng cho cửa chính và công trình yêu cầu vẻ chắc chắn. <strong>Gỗ Gõ đỏ</strong> có tông màu ấm cùng vân gỗ nổi bật, phù hợp với không gian cổ điển, tân cổ điển. <strong>Gỗ Óc chó (Walnut)</strong> có màu nâu trầm và đường vân mềm mại, thường kết hợp với nội thất hiện đại.</p><p>Quy trình tẩm sấy và kiểm soát độ ẩm giúp hạn chế cong vênh, co ngót khi sử dụng. Cửa pano gỗ là lựa chọn cho kiến trúc cổ điển và tân cổ điển.</p>${illustration('cua-go-vom-go-eurowindow.jpg','Cua go dang vom')}<h3>3.2. Cửa gỗ công nghiệp</h3><p>Cửa gỗ MDF có bề mặt phẳng, thuận tiện hoàn thiện theo thiết kế hiện đại. Cửa HDF có mật độ sợi gỗ cao hơn MDF và được sử dụng cho cửa thông phòng, phòng ngủ. Bề mặt veneer tạo vân gỗ tự nhiên; laminate tăng khả năng chống trầy xước; melamine có nhiều lựa chọn màu sắc cho nội thất dân dụng.</p>${illustration('cua-go-cong-nghiep-eurowindow.webp','Cua go cong nghiep Eurowindow','eurowindow-products')}<h3>3.3. Cửa gỗ ghép thanh</h3><p>Cửa gỗ ghép thanh được tạo từ các thanh gỗ tự nhiên đã qua xử lý, ghép thành tấm cửa và hoàn thiện bằng lớp veneer. Veneer Sồi mang gam màu sáng; veneer Lim có tông trầm; veneer Gõ đỏ tạo điểm nhấn với màu ấm; veneer Walnut phù hợp với không gian hiện đại. Kết cấu ghép thanh giữ vẻ đẹp của gỗ tự nhiên và tăng độ ổn định cho cánh cửa.</p>${illustration('cua-di-go-panel-do-eurowindow.jpg','Cua go panel mau do')}<h3>3.4. Cửa gỗ composite</h3><p>Cửa gỗ composite được tạo từ hỗn hợp bột gỗ, nhựa PVC và phụ gia, có kết cấu ổn định và khả năng kháng nước cao. Các lựa chọn hoàn thiện gồm phủ da vân gỗ, sơn PU, sơn vân gỗ và thiết kế tân cổ điển. Khả năng kháng nước khiến dòng cửa này phù hợp với phòng tắm, nhà vệ sinh và khu vực có độ ẩm cao.</p>${illustration('cua-go-composite-eurowindow.webp','Cua go composite Eurowindow','eurowindow-products')}<h3>3.5. Cửa gỗ chống cháy</h3><p>Cửa gỗ chống cháy có kết cấu nhiều lớp gồm vật liệu chống cháy, lớp cách nhiệt và lớp hoàn thiện bề mặt. Dòng cửa này được sử dụng tại chung cư, khách sạn, văn phòng và công trình có yêu cầu an toàn cháy. Bề mặt hoàn thiện gồm veneer, melamine, laminate hoặc sơn. Cấp chịu lửa và cấu tạo của cửa được lựa chọn theo yêu cầu an toàn cháy tại từng vị trí trong công trình.</p>${illustration('cua-go-chong-chay-eurowindow.webp','Cua go tai cong trinh','eurowindow-products')}<h2>4. Kinh nghiệm lựa chọn cửa gỗ phù hợp</h2><h3>4.1. Chọn cửa theo vị trí lắp đặt</h3><p>Cửa chính cần kết cấu chắc chắn và kiểu dáng hài hòa với mặt tiền; cửa gỗ tự nhiên, gỗ ghép thanh hoặc cửa chống cháy đáp ứng các hướng lựa chọn này. Cửa phòng ngủ và phòng làm việc sử dụng cửa gỗ công nghiệp hoặc gỗ ghép thanh để đồng bộ với nội thất. Phòng tắm và khu vực ẩm sử dụng cửa composite hoặc dòng cửa có khả năng chống ẩm.</p>${illustration('cua-go-tu-nhien-phong-cach-sang-trong-eurowindow.webp','Cua go tu nhien trong khong gian noi that','eurowindow-products')}<h3>4.2. Chọn cửa theo phong cách kiến trúc</h3><p>Thiết kế phẳng, ít chi tiết phù hợp với kiến trúc hiện đại. Cửa pano và đường chỉ trang trí nhẹ kết hợp hài hòa với phong cách tân cổ điển. Không gian cổ điển sử dụng cửa có chi tiết trang trí và vân gỗ tự nhiên.</p>${illustration('cua-go-vom-trang-eurowindow.jpg','Cua go mau trang voi khung vom')}${illustration('cua-go-tu-nhien-cac-dong-go-eurowindow.webp','Cac dong go tu nhien Eurowindow','eurowindow-products')}<h2>5. Mẫu gỗ và mẫu veneer của cửa gỗ Eurowindow</h2><p>Cửa gỗ Eurowindow có lựa chọn màu sắc và vân gỗ khác nhau, kết hợp với nội thất từ phong cách hiện đại đến cổ điển. Gỗ Lim có tông nâu vàng đến nâu sẫm và vân rõ, phù hợp với không gian truyền thống hoặc nội thất tông trầm. Gỗ Sồi có gam sáng, dễ phối với màu trắng, kem và be. Gỗ Gõ đỏ có sắc đỏ nâu ấm cùng vân nổi bật, tạo điểm nhấn cho biệt thự và nội thất cổ điển, tân cổ điển.</p><p>Veneer Lim phối hợp với nội thất tông trầm; veneer Sồi tạo sắc thái sáng, thoáng; veneer Gõ đỏ đồng bộ với các chi tiết gỗ có màu ấm.</p>${illustration('cua-go-tu-nhien-vat-lieu-eurowindow.webp','Vat lieu cua go tu nhien Eurowindow','eurowindow-products')}<h2>6. Hệ phụ kiện của cửa gỗ Eurowindow</h2><p>Phụ kiện phù hợp với từng dòng cửa giúp bộ cửa vận hành ổn định và thuận tiện. Tay nắm hỗ trợ thao tác đóng mở và hoàn thiện thiết kế. Bản lề 3D cho phép căn chỉnh cánh theo nhiều hướng; bản lề lá tạo liên kết chắc chắn cho cửa đi gỗ. Khóa giữ cửa ở trạng thái đóng và đáp ứng nhu cầu sử dụng tại từng vị trí.</p>${illustration('cua-go-chong-chay-gioang-ngan-khoi-eurowindow.webp','Chi tiet gioang cua go','eurowindow-products')}<h2>7. Một số mẫu kính hoa văn của cửa gỗ Eurowindow</h2><p>Kính hoa văn tạo điểm nhấn trang trí cho cửa gỗ. Các họa tiết gồm đường nét cổ điển mềm mại và hình học hiện đại, kết hợp với khung gỗ để hài hòa cùng phong cách nội thất. Cửa gỗ pano kính kết hợp mảng gỗ và kính trong cùng thiết kế, tạo lựa chọn cho không gian cần điểm nhấn trang trí.</p><h2>8. Ưu điểm của cửa gỗ Eurowindow</h2><p>Các dòng cửa gỗ Eurowindow kết hợp lựa chọn vật liệu, cấu tạo cánh, bề mặt hoàn thiện và phụ kiện để đáp ứng yêu cầu thẩm mỹ, vận hành và sử dụng lâu dài.</p>${illustration('cua-go-ghep-thanh-eurowindow.webp','Cua go ghep thanh Eurowindow','eurowindow-products')}<h3>8.1. Vật liệu ổn định, hạn chế cong vênh và co ngót</h3><p>Nguyên liệu gỗ được xử lý, tẩm sấy theo độ ẩm xuất khẩu khoảng 12–14%. Gỗ rừng trồng dùng cho sản phẩm ghép thanh tiếp tục được xử lý biến tính trước khi sản xuất, giúp cải thiện độ ổn định, độ cứng và độ bền vật liệu. Quy trình này hạn chế cong vênh, co ngót khi thời tiết và độ ẩm thay đổi.</p><h3>8.2. Đóng mở êm, kín khít, hỗ trợ cách âm và cách nhiệt</h3><p>Cửa gỗ Eurowindow sử dụng hệ gioăng chuyên dụng nhập khẩu từ châu Âu, kết hợp bản lề có khả năng cân chỉnh và phụ kiện đồng bộ. Các chi tiết này tạo độ kín giữa cánh và khuôn, giúp cửa đóng mở nhẹ nhàng. Độ kín của bộ cửa hạn chế truyền âm và trao đổi nhiệt qua khe hở; cấu tạo cánh và chất lượng lắp đặt quyết định hiệu quả sử dụng.</p>${illustration('cua-go-composite-anh-ky-thuat-eurowindow.webp','Anh ky thuat cua go composite','eurowindow-products')}<h3>8.3. Bề mặt hoàn thiện đồng đều</h3><p>Gỗ được kiểm soát trước khi gia công và hoàn thiện bằng hệ thống phun sơn công nghiệp tự động. Quy trình tạo bề mặt đồng đều, hạn chế sai lệch màu giữa các bộ phận và bảo vệ bề mặt trong quá trình sử dụng.</p>${illustration('cua-go-cong-nghiep-be-mat-eurowindow.webp','Be mat cua go cong nghiep','eurowindow-products')}<h3>8.4. Thi công thuận tiện ở giai đoạn hoàn thiện</h3><p>Khuôn và cửa gỗ Eurowindow được thiết kế cho phương án lắp dựng công nghiệp ở giai đoạn cuối của quá trình hoàn thiện. Thiết kế hỗ trợ vận chuyển, lắp đặt và hoàn thiện tại công trường, rút ngắn thời gian thi công và giảm ảnh hưởng đến các hạng mục hoàn thiện khác.</p>${illustration('cua-go-cong-nghiep-ket-cau-eurowindow.webp','Ket cau cua go cong nghiep','eurowindow-products')}<h3>8.5. Độ bền và hiệu quả sử dụng lâu dài</h3><p>Quy trình xử lý nguyên liệu, gia công, hoàn thiện bề mặt và lựa chọn phụ kiện giúp cửa duy trì công năng trong quá trình sử dụng. Độ ổn định của vật liệu hạn chế nhu cầu sửa chữa do cong vênh, co ngót. Mẫu cửa gỗ phòng khách được lựa chọn theo màu sắc, kiểu dáng và vật liệu nội thất của công trình.</p>${illustration('cua-di-go-doi-eurowindow.jpg','Cua go doi trong khong gian noi that')}</article></div></section>`;
    }
    if(slug==='cua-cuon'){const imageRoot='/images/product-library/Cua-cuon/Cua-cuon-khe-thoang-easd45/';const illustration=(file,alt)=>`<figure class="aluminum-editorial-figure"><img src="${file}" alt="${alt}" loading="lazy" decoding="async"></figure>`;return `<section class="section aluminum-editorial"><div class="wrap"><article class="aluminum-editorial-content"><p>Cửa cuốn nhôm Eurowindow là giải pháp cho nhà phố, cửa hàng, gara ô tô và công trình thương mại. Dòng cửa cuốn nhôm khe thoáng kết hợp nan mành, hệ thống điều khiển và các tính năng an toàn, đáp ứng nhu cầu bảo vệ, vận hành thuận tiện và hoàn thiện mặt tiền.</p><h2>1. Thiết kế cửa cuốn hiện đại cho mặt tiền</h2><h3>1.1. Khe thoáng lấy sáng, thông gió</h3><p>Nan cửa có khe thoáng giúp không khí lưu thông và ánh sáng tự nhiên đi qua khi cửa đóng. Thiết kế này phù hợp với tầng một, gara và khu vực kinh doanh cần duy trì sự thông thoáng.</p>${illustration("/images/eurowindow-products/cua-cuon-nhom-khe-thoang-easd45-khe-thoang-eurowindow.webp","Nan cua cuon co khe thoang")}<h3>1.2. Màu sơn phù hợp kiến trúc</h3><p>Nan mành được hoàn thiện bằng dây chuyền sơn của Eurowindow. Các lựa chọn màu sắc phối hợp với mặt tiền nhà phố, shophouse và biệt thự.</p>${illustration(imageRoot+'Cua-cuon-khe-thoang-easd45-01.webp','Cua cuon tai mat tien cong trinh')}<h3>1.3. Cuốn gọn, tiết kiệm diện tích</h3><p>Khi mở, thân cửa cuộn lên phía trên hộp cửa, không cần khoảng quét của cánh mở truyền thống. Cơ chế này giải phóng diện tích phía trước lối vào, phù hợp với mặt tiền có chiều rộng hạn chế.</p>${illustration("/images/eurowindow-products/cua-cuon-nhom-khe-thoang-easd45-van-hanh-eurowindow.webp","Cua cuon EASD45 trong qua trinh van hanh")}<h3>1.4. Vật liệu nhôm nhẹ, chống oxy hóa</h3><p>Nan nhôm có trọng lượng nhẹ hơn một số dòng cửa cuốn thép truyền thống và có khả năng chống oxy hóa. Đặc tính vật liệu giúp giảm tải cho hệ thống vận hành, đồng thời hạn chế ảnh hưởng của môi trường trong quá trình sử dụng.</p>${illustration(imageRoot+'Cua-cuon-khe-thoang-easd45-05.webp','Cua cuon nhom tai loi vao cong trinh')}<h2>2. Công nghệ điều khiển và an toàn</h2><h3>2.1. Điều khiển mã số trượt</h3><p>Bộ điều khiển từ xa sử dụng công nghệ mã số trượt (rolling code), thay đổi mã sau mỗi lần sử dụng. Cơ chế này hạn chế nguy cơ sao chép tín hiệu so với mã cố định.</p>${illustration("/images/eurowindow-products/cua-cuon-nhom-khe-thoang-easd45-dieu-khien-eurowindow.webp","Bo dieu khien cua cuon EASD45")}<h3>2.2. Cảm biến vật cản, tự động đảo chiều</h3><p>Cảm biến an toàn nhận biết vật cản trong quá trình đóng mở và kích hoạt cửa dừng hoặc đảo chiều, góp phần hạn chế va chạm.</p>${illustration("/images/eurowindow-products/cua-cuon-nhom-khe-thoang-easd45-cam-bien-eurowindow.webp","Cam bien an toan cua cuon EASD45")}<h3>2.3. Kết nối hệ thống phòng cháy chữa cháy</h3><p>Cửa có tiếp điểm kết nối với hệ thống báo cháy của công trình. Khi nhận tín hiệu báo cháy, cửa vận hành theo phương án được thiết lập cho công trình, hỗ trợ xử lý sự cố và thoát hiểm.</p>${illustration("/images/eurowindow-products/cua-cuon-nhom-khe-thoang-easd45-pccc-eurowindow.webp","Ket noi cua cuon voi he thong PCCC")}<h2>3. Ứng dụng cửa cuốn nhôm Eurowindow</h2><p>Cửa cuốn nhôm Eurowindow được lắp đặt tại nhà phố, cửa hàng mặt phố, gara ô tô, nhà kho và mặt tiền shophouse. Nan khe thoáng hỗ trợ lưu thông không khí khi cửa đóng; cơ chế cuốn gọn giải phóng diện tích trước lối vào.</p>${illustration(imageRoot+'Cua-cuon-khe-thoang-easd45-09.webp','Cua cuon nhom tai cong trinh nha o')}</article></div></section>`;}
    if(slug==='cua-thong-minh-the-he-moi')return `<section class="section aluminum-editorial"><div class="wrap"><article class="aluminum-editorial-content"><p>Cửa thông minh thế hệ mới Eurowindow kết hợp khả năng tự động vận hành, điều khiển từ xa và kết nối hệ sinh thái nhà thông minh. Danh mục gồm các giải pháp nhận diện khuôn mặt, điều khiển bằng giọng nói, cửa tự động và kính công nghệ cao cho nhà ở, văn phòng và công trình dịch vụ.</p><h2>1. Tổng quan về cửa thông minh thế hệ mới</h2><p>Cửa thông minh tích hợp công nghệ vào quá trình đóng mở, kiểm soát ra vào và vận hành trong công trình. Người dùng điều khiển sản phẩm qua giọng nói, ứng dụng điện thoại, thiết bị điều khiển từ xa, nhận diện khuôn mặt hoặc cảm biến môi trường theo từng dòng sản phẩm.</p><p>Trong các công trình dân dụng và thương mại, cửa thông minh hỗ trợ quản lý vận hành và tăng tiện nghi sử dụng. Với hơn 24 năm tiên phong tiêu chuẩn châu Âu tại Việt Nam, Eurowindow đưa các công nghệ cửa thông minh vào sản xuất và phân phối trong nước.<figure class="aluminum-editorial-figure"><img src="/i/don-dau-xu-huong-kien-truc-hien-dai-voi-thiet-ke-nha-smarthome-cac-giai-phap-cua-thong-minh-dang-ngay-cang-duoc-ua-chuong-boi-tinh-tham-my-tien-nghi-va-an-toan.jpg.webp" alt="Cửa thông minh trong không gian nhà ở hiện đại" loading="lazy" decoding="async"></figure><p>Các dòng cửa tích hợp công nghệ điều khiển, bảo mật và cảm biến theo chức năng riêng của từng sản phẩm.</p><h3>2.1. Công nghệ bảo mật đa lớp</h3><p>Khóa nhận diện khuôn mặt sử dụng công nghệ Liveness Check để phân biệt khuôn mặt thật với ảnh phẳng. Hệ thống xác thực trong chưa đầy một giây và kích hoạt mở khóa từ xa trong 3–4 giây. Khi phát hiện người lạ xuất hiện liên tục trong vùng nhận diện, thiết bị chụp ảnh và gửi cảnh báo đến điện thoại gia chủ.</p><p>Nguồn điện của khóa và camera được bố trí riêng, giúp hai thiết bị hoạt động độc lập. Nhận diện khuôn mặt hỗ trợ kiểm soát ra vào và mở khóa không tiếp xúc.<figure class="aluminum-editorial-figure"><img src="/i/cong-nghe-nhan-dien-khuon-mat-mot-trong-nhung-cong-nghe-bao-mat-da-lop-noi-bat-cua-cua-eurowindow-cho-phep-kich-hoat-nhan-dien-nhanh-chong-han-che-nguy-co-gia-mao-va-ho-tro-mo-k.jpg.webp" alt="Công nghệ nhận diện khuôn mặt trên cửa thông minh" loading="lazy" decoding="async"></figure><p>Các sản phẩm cửa thông minh hỗ trợ phương thức điều khiển theo từng dòng, gồm ứng dụng điện thoại, thiết bị điều khiển từ xa, nút bấm gắn tường và giọng nói. Kết nối với hệ sinh thái Smarthome giúp người dùng quản lý hoạt động đóng mở và theo dõi lịch sử vận hành qua ứng dụng.</p><p>Cửa sổ tự động điều khiển bằng giọng nói Eurowindow là sản phẩm đầu tiên tại Việt Nam hỗ trợ tiếng Việt. Người dùng ra lệnh đóng mở tự nhiên mà không cần ghi nhớ cú pháp tiếng Anh.<figure class="aluminum-editorial-figure"><img src="/i/cong-nghe-nhan-dien-khuon-mat-mot-trong-nhung-cong-nghe-bao-mat-da-lop-noi-bat-cua-cua-eurowindow-cho-phep-kich-hoat-nhan-dien-nhanh-chong-han-che-nguy-co-gia-mao-va-ho-tro-mo-k.jpg.webp" alt="Nhận diện khuôn mặt hỗ trợ quản lý cửa thông minh" loading="lazy" decoding="async"></figure><p>Cảm biến được lựa chọn theo công năng của từng sản phẩm. Cửa bản lề sàn tự động trang bị cảm biến va chạm trên cánh và cảm biến lực trên bản lề, giúp cửa dừng khi gặp vật cản.</p><p>Cửa mái kính Skylight phản ứng trong 3 giây với tín hiệu cảm biến mưa, gió để tự động đóng; cửa tự động mở khi hệ thống báo khói kích hoạt. Cửa gấp trượt dọc tự động tích hợp lựa chọn cảm biến chống kẹp tay và cảm biến mưa.</p><h2>3. Các dòng sản phẩm cửa thông minh Eurowindow</h2><p>Danh mục cửa thông minh Eurowindow gồm các giải pháp cửa, vách và kính với phương thức vận hành và công năng riêng.</p><h3>3.1. Cửa trượt Slim ray treo</h3><p>Cửa trượt Slim ray treo sử dụng ray giấu trên trần, không có ray sàn. Khung nhôm thanh mảnh, cơ chế đóng mở liên động và phụ kiện giảm chấn giúp cửa vận hành êm, hạn chế va đập. Thiết kế phù hợp phòng ngủ, phòng làm việc, phòng khách liền bếp, vách ngăn nội thất, căn hộ, nhà phố và văn phòng nhỏ cần tiết kiệm diện tích, mở rộng tầm nhìn.<figure class="aluminum-editorial-figure"><img src="/images/eurowindow-products/cua-truot-slim-ray-treo-01.webp" alt="Cửa trượt Slim ray treo Eurowindow" loading="lazy" decoding="async"></figure><h3>3.2. Rèm trong hộp kính</h3><p>Rèm trong hộp kính nằm giữa hai lớp kính, vận hành bằng cơ cấu nam châm hoặc động cơ điện điều khiển từ xa. Rèm điều chỉnh ánh sáng, hạn chế bụi bẩn và giữ bề mặt kính gọn sạch. Sản phẩm hỗ trợ tiết kiệm năng lượng đến 40%, chống UV-35 và sử dụng hạt hút ẩm để giảm ngưng tụ, nấm mốc; rèm gần như không cần vệ sinh trong suốt quá trình sử dụng.</p><p>Rèm phù hợp phòng tắm, phòng đọc sách, phòng làm việc, vách kính, cửa sổ, cửa đi, văn phòng và khách sạn.<figure class="aluminum-editorial-figure"><img src="/images/product-library/Cua-thong-minh-the-he-moi/Rem-trong-hop-kinh/Rem-trong-hop-kinh-02.webp" alt="Rèm tích hợp trong hộp kính" loading="lazy" decoding="async"></figure><h3>3.3. Kính điện đổi màu</h3><p>Kính điện đổi màu chuyển giữa trạng thái trong suốt và mờ đục bằng công tắc, remote hoặc ứng dụng. Độ truyền sáng đạt trên 85% khi bật điện; khả năng cản sáng trên 90% khi tắt điện, cản tia UV trên 98% và tia hồng ngoại trên 60%.</p><p>Kính có tuổi thọ trên 10 năm và chịu hơn 8 triệu lần bật/tắt. Sản phẩm thay thế rèm, decal dán kính và làm màn chiếu ở chế độ mờ; phù hợp phòng tắm, phòng ngủ, phòng họp, mái kính, vách ngăn sân vườn, hồ bơi và không gian cần điều chỉnh riêng tư.<figure class="aluminum-editorial-figure"><img src="/images/eurowindow-products/kinh-dien-doi-mau-04.webp" alt="Kính điện đổi màu Eurowindow" loading="lazy" decoding="async"></figure><h3>3.4. Cửa bản lề sàn tự động</h3><p>Cửa mở quay hai chiều tự động có góc mở tùy chỉnh đến 90° mỗi chiều, vận hành bằng cảm biến chuyển động, remote hoặc nút bấm. Cảm biến va chạm trên cánh, cảm biến lực trên bản lề và bộ lưu điện dự phòng hỗ trợ vận hành an toàn. Cửa kết nối hệ thống báo cháy theo cấu hình của công trình.</p><p>Profile dày đến 2 mm kết hợp gân tăng cứng tạo kết cấu chịu lực. Cửa phù hợp sảnh đón khách, trung tâm thương mại, văn phòng, khách sạn và khu vực ngăn cách trong nhà ở.<figure class="aluminum-editorial-figure"><img src="/images/eurowindow-products/cua-ban-le-san-tu-dong-03.webp" alt="Cửa bản lề sàn tự động Eurowindow" loading="lazy" decoding="async"></figure><h3>3.5. Cửa gấp trượt dọc tự động</h3><p>Cửa gấp trượt dọc tự động kết hợp vách kính lấy sáng với cơ chế gấp trượt theo phương dọc, tạo mái che khi vận hành. Hệ cửa hỗ trợ thông gió tự nhiên, điều khiển bằng remote hoặc nút bấm; cảm biến chống kẹp tay và cảm biến mưa là các lựa chọn tích hợp.</p><p>Động cơ vận hành êm. Giải pháp phù hợp biệt thự, sân vườn, quán cà phê, khu vực ngoài trời và không gian cần thay đổi cách sử dụng.<figure class="aluminum-editorial-figure"><img src="/images/eurowindow-products/cua-gap-truot-doc-tu-dong-02.webp" alt="Cửa gấp trượt dọc tự động Eurowindow" loading="lazy" decoding="async"></figure><h3>3.6. Cửa sổ tự động điều khiển bằng giọng nói</h3><p>Cửa sổ điều khiển bằng giọng nói tiếng Việt nhận lệnh đóng mở qua khẩu lệnh, remote, ứng dụng điện thoại hoặc nút bấm. Sản phẩm có bốn kiểu mở: quay trong, quay ngoài, quay lật trong và hất ngoài. Một số kiểu mở đạt khả năng cách âm đến 40 dB; cảm biến mưa, gió hỗ trợ vận hành tự động.</p><p>Cửa kết nối hệ sinh thái Smarthome, phù hợp phòng ngủ, phòng khách, phòng làm việc, nhà phố, căn hộ cao cấp, biệt thự và công trình nhà thông minh.<figure class="aluminum-editorial-figure"><img src="/images/eurowindow-products/cua-so-tu-dong-dieu-khien-bang-giong-noi-01.webp" alt="Cửa sổ tự động điều khiển bằng giọng nói" loading="lazy" decoding="async"></figure><h3>3.7. Vách trượt dọc tự động</h3><p>Vách trượt dọc tự động chuyển từ vách kính cố định thành ô thoáng tích hợp lan can kính mà không mở rộng diện tích xây dựng. Hệ vách vận hành bằng dây xích thép không gỉ, tích hợp khóa an toàn Comfort Lock, khóa đa điểm và thiết kế chống kẹt tay. Từng lớp kính tháo rời để vệ sinh.</p><p>Khung nhôm thanh mảnh hỗ trợ lấy sáng, đón gió, cách âm, cách nhiệt và mở rộng tầm nhìn. Vách phù hợp ban công, lan can tầng cao, mặt tiền tòa nhà, khách sạn và công trình kiến trúc hiện đại.<figure class="aluminum-editorial-figure"><img src="/images/eurowindow-products/vach-truot-doc-tu-dong-01.webp" alt="Vách trượt dọc tự động Eurowindow" loading="lazy" decoding="async"></figure><h3>3.8. Cửa lưới chống muỗi</h3><p>Cửa lưới chống muỗi Eurowindow ngăn muỗi, kiến ba khoang, gián và bọ mà không cần dùng hóa chất. Sản phẩm có xuất xứ Italia, đạt tiêu chuẩn châu Âu và tương thích với nhiều hệ cửa nhôm, nhựa, gỗ. Sợi lưới mỏng, độ trong suốt cao duy trì khả năng lấy sáng, thông gió và thẩm mỹ.</p><p>Lưới tháo rời để vệ sinh, vận hành trơn tru, tích hợp phanh động lực an toàn và hỗ trợ chống tia cực tím, phấn hoa. Sản phẩm phù hợp cửa sổ, cửa đi, phòng ngủ, phòng bếp và khu vực cần thông gió tự nhiên.<figure class="aluminum-editorial-figure"><img src="/images/product-library/Cua-thong-minh-the-he-moi/Cua-luoi-chong-muoi/Cua-luoi-chong-muoi-06.webp" alt="Cửa lưới chống muỗi Eurowindow" loading="lazy" decoding="async"></figure><h3>3.9. Cửa sổ đẩy ngang tự động</h3><p>Cửa sổ đẩy ngang tự động có cánh mở song song với khung, tiết kiệm diện tích tại vị trí hạn chế không gian hoặc khó thao tác bằng tay. Hệ cửa vận hành êm, điều khiển qua remote hoặc ứng dụng; người dùng điều chỉnh độ mở, dừng cánh tại các vị trí và quản lý cảm biến thời tiết.</p><p>Sản phẩm phù hợp nhà phố, căn hộ cao tầng, văn phòng, phòng tắm kính, nhà bếp và cửa sổ tầng cao cần tăng thông gió tự nhiên.<figure class="aluminum-editorial-figure"><img src="/images/eurowindow-products/cua-so-day-ngang-tu-dong-01.webp" alt="Cửa sổ đẩy ngang tự động Eurowindow" loading="lazy" decoding="async"></figure><h3>3.10. Cửa trượt tự động</h3><p>Cửa trượt tự động Eurowindow sử dụng động cơ tích hợp trên khung để đóng mở. Sản phẩm lắp cho cửa hai cánh hoặc bốn cánh, dùng trong công trình mới và công trình đã có cửa trượt.</p><p>Hộp ray nhỏ, động cơ vận hành êm, sức kéo tối đa 180 kg và khóa tích hợp. Cửa phù hợp siêu thị, trung tâm thương mại, khách sạn, bệnh viện, văn phòng và không gian cần lưu thông thuận tiện.<figure class="aluminum-editorial-figure"><img src="/images/product-library/Cua-thong-minh-the-he-moi/Cua-truot-tu-dong/Cua-truot-tu-dong-04.webp" alt="Cửa trượt tự động Eurowindow" loading="lazy" decoding="async"></figure><h3>3.11. Cửa mái kính Skylight</h3><p>Cửa mái kính Skylight lấy sáng tự nhiên, thông gió, thoát nhiệt và hỗ trợ an toàn cho công trình. Cửa đóng mở tự động, phản ứng với cảm biến mưa, gió trong 3 giây và tự động mở thoát khói khi phát hiện hỏa hoạn. Hệ cửa vận hành đến 10.000 lần, sử dụng động cơ điện áp an toàn 24 V.</p><p>Sản phẩm phù hợp mái kính, giếng trời, sảnh thông tầng, phòng tắm, văn phòng, trung tâm thương mại, khách sạn, khu nghỉ dưỡng và công trình cần giải pháp thoát khói theo tiêu chuẩn PCCC.<figure class="aluminum-editorial-figure"><img src="/images/product-library/Cua-thong-minh-the-he-moi/Cua-mai-kinh-skylight/Cua-mai-kinh-skylight-02.webp" alt="Cửa mái kính Skylight Eurowindow" loading="lazy" decoding="async"></figure><h3>3.12. Cửa sổ tự động</h3><p>Cửa sổ tự động đóng mở bằng remote hoặc nút bấm. Cảm biến mưa, gió hỗ trợ bảo vệ công trình và người sử dụng. Hệ cửa phù hợp phòng ngủ, phòng khách, phòng làm việc, căn hộ, nhà phố, biệt thự và vị trí cần thao tác đóng mở thuận tiện.<figure class="aluminum-editorial-figure"><img src="/images/door-reference/smart-Cua-so-tu-dong-dieu-khien-bang-giong-noi.jpg" alt="Cửa sổ tự động Eurowindow tại công trình" loading="lazy" decoding="async"></figure><h2>4. Ứng dụng cửa thông minh Eurowindow</h2><p><strong>Nhà phố và biệt thự:</strong> Khóa nhận diện khuôn mặt tại lối vào, cửa sổ điều khiển bằng giọng nói trong phòng ngủ, rèm hộp kính tại phòng tắm và kính điện đổi màu trong phòng ngủ chính.</p><p><strong>Căn hộ cao cấp:</strong> Cửa sổ đẩy ngang kết hợp cảm biến gió và vách trượt dọc tại ban công.</p><p><strong>Văn phòng:</strong> Kính điện đổi màu cho phòng họp, cửa trượt tự động tại lối vào và cửa bản lề sàn tại khu vực tiếp khách.</p><p><strong>Khách sạn, khu nghỉ dưỡng:</strong> Cửa mái kính Skylight tại khu vực hồ bơi, rèm hộp kính trong phòng khách sạn và cửa gấp trượt dọc tại khu ẩm thực ngoài trời.</p><p><strong>Công trình thương mại:</strong> Cửa trượt tự động bốn cánh tại lối vào trung tâm thương mại và cửa mái Skylight tại sảnh thông tầng, đáp ứng yêu cầu PCCC của công trình.</p><p><strong>Không gian cần riêng tư:</strong> Kính điện đổi màu cho vách phòng tắm, phòng khám và phòng tư vấn.</p><p><strong>Nhà thông minh:</strong> Các dòng cửa kết nối ứng dụng điện thoại hoặc điều khiển bằng giọng nói theo phương thức vận hành của từng sản phẩm.</p></article></div></section>`;
    if(slug==='vach-kinh-mat-dung')return "<section class=\"section aluminum-editorial\"><div class=\"wrap\"><article class=\"aluminum-editorial-content\"><h2>1. Ưu điểm nổi bật của sản phẩm kính Eurowindow</h2><h3>1.1. Độ an toàn cao, phù hợp nhiều hạng mục công trình</h3><figure class=\"aluminum-editorial-figure\"><img src=\"/images/product-library/San-pham-kinh/Kinh-an-toan/Kinh-an-toan-01.webp\" alt=\"Độ an toàn cao, phù hợp nhiều hạng mục công trình – kính Eurowindow\" loading=\"lazy\" decoding=\"async\"></figure><p>Kính Eurowindow được sản xuất trên dây chuyền hiện đại, được ứng dụng cho nhiều hạng mục như vách kính lớn, vách ngăn, cửa thủy lực, lan can cầu thang, cửa sổ, cửa đi, buồng tắm kính, bàn kính hoặc cửa xe ô tô.</p><p>Các dòng kính như kính cường lực, kính bán cường lực và kính dán an toàn có khả năng chịu lực cơ học tốt, giúp tăng độ an toàn khi sử dụng trong nhà ở, công trình dân dụng và công trình công nghiệp.</p><h3>1.2. Đáp ứng nhiều tiêu chuẩn chất lượng quốc tế</h3><figure class=\"aluminum-editorial-figure\"><img src=\"/images/product-library/San-pham-kinh/Kinh-an-toan/Kinh-an-toan-02.webp\" alt=\"Đáp ứng nhiều tiêu chuẩn chất lượng quốc tế – kính Eurowindow\" loading=\"lazy\" decoding=\"async\"></figure><p>Sản phẩm kính Eurowindow được Viện Tiêu chuẩn Anh BSI cấp chứng chỉ Kitemark và đáp ứng nhiều tiêu chuẩn quốc tế như BS EN 12150-1:2000, BS EN 14449:2005, BS EN 1279-2:2002, EN 1863, ANSI Z97.1-2004, ECE R43. Đây là cơ sở quan trọng cho thấy sản phẩm được kiểm soát theo các yêu cầu nghiêm ngặt về chất lượng, độ bền và độ an toàn trong quá trình sử dụng.</p><h3>1.3. Sản xuất trên dây chuyền hiện đại, kiểm soát chất lượng chặt chẽ</h3><figure class=\"aluminum-editorial-figure\"><img src=\"/images/vach-kinh-user/cac-san-pham-kinh-cua-eurowindow-duoc-gia-cong-dong-bo-dam-bao-do-chinh-xac-truoc-khi-dua-vao-cong-trinh.jpg.webp\" alt=\"Kính Eurowindow được gia công đồng bộ trước khi đưa vào công trình\" loading=\"lazy\" decoding=\"async\"></figure><p>Eurowindow đầu tư Trung tâm gia công kính tại Khu công nghiệp Quang Minh, Mê Linh, Hà Nội với hệ thống thiết bị nhập khẩu từ các quốc gia châu Âu như Italia, Phần Lan, Thụy Sĩ và Đức. Trung tâm được trang bị máy cắt kính khổ lớn, máy mài song cạnh, máy khoan, máy gia công CNC, lò tôi kính phẳng, dây chuyền sản xuất kính dán an toàn, dây chuyền sản xuất hộp kính và thiết bị kiểm tra Heat-Soak-Test để loại bỏ kính lỗi sau khi tôi.</p><p>Nhờ đó, sản phẩm kính được gia công đồng bộ, đảm bảo độ chính xác và tính ổn định trước khi đưa vào công trình.</p><h3>1.4. Gia công được kính khổ lớn, đáp ứng thiết kế hiện đại</h3><figure class=\"aluminum-editorial-figure\"><img src=\"/images/eurowindow-products/hop-kinh-kho-lon-eurowindow.webp\" alt=\"Gia công được kính khổ lớn, đáp ứng thiết kế hiện đại – kính Eurowindow\" loading=\"lazy\" decoding=\"async\"></figure><p>Trung tâm kính Eurowindow có khả năng tôi kính cường lực và bán cường lực với độ dày từ 4mm đến 19mm, kích thước tối đa lên đến 2.800 × 6.000mm. Khả năng gia công kính khổ lớn giúp sản phẩm phù hợp với các công trình cần mở rộng tầm nhìn, tăng diện tích lấy sáng và tạo hiệu ứng không gian thông thoáng như mặt dựng kính, vách kính lớn, showroom, sảnh tòa nhà hoặc các công trình kiến trúc hiện đại.</p><h3>1.5. Cách âm, cách nhiệt và hỗ trợ tiết kiệm năng lượng</h3><figure class=\"aluminum-editorial-figure\"><img src=\"/images/vach-kinh-user/kinh-can-nhiet-low-e-phu-lop-kim-loai-sieu-mong-co-kha-nang-han-che-khoang-40-su-truyen-nhiet-vao-mua-he-chong-nong-hieu-qua-on-dinh-nhiet-do-trong-nha.jpg.webp\" alt=\"Kính Low-E Eurowindow hạn chế truyền nhiệt qua kính\" loading=\"lazy\" decoding=\"async\"></figure><p>Kính Eurowindow có khả năng cách âm, cách nhiệt, hỗ trợ kiểm soát nhiệt độ và tiếng ồn trong không gian sử dụng. Đặc biệt, Eurowindow ứng dụng công nghệ tôi kính Super Soft Coating Low-e 0,01, giúp hạn chế bức xạ mặt trời, giảm hấp thụ và truyền nhiệt qua kính. Nhờ đó, công trình vẫn đảm bảo ánh sáng tự nhiên nhưng giảm áp lực cho hệ thống điều hòa, góp phần tiết kiệm điện năng và phù hợp với xu hướng kiến trúc xanh.</p><h3>1.6. Tăng tính thẩm mỹ và linh hoạt trong thiết kế</h3><p>Bên cạnh kính cường lực, kính bán cường lực và hộp kính, Eurowindow còn cung cấp nhiều dòng kính như kính hoa văn, kính an toàn, kính phản quang, kính phủ cứng, phủ mềm. Sự đa dạng này giúp kiến trúc sư và chủ đầu tư dễ dàng lựa chọn loại kính phù hợp với từng không gian, từ khu vực cần sự trong suốt, mở rộng tầm nhìn đến khu vực cần tính riêng tư hoặc điểm nhấn trang trí.</p><h2>2. Điểm đặc biệt trong công nghệ gia công kính của Eurowindow</h2><h3>2.1. Quy trình gia công kính được tổ chức đồng bộ trong một trung tâm chuyên biệt</h3><figure class=\"aluminum-editorial-figure\"><img src=\"/images/vach-kinh-user/10.jpg.webp\" alt=\"Gia công kính tại trung tâm kính Eurowindow\" loading=\"lazy\" decoding=\"async\"></figure><p>Thay vì phụ thuộc vào nhiều đơn vị gia công, các công đoạn như cắt kính, mài cạnh, khoan lỗ, gia công CNC, tôi kính, sản xuất kính dán an toàn và hộp kính đều được thực hiện trong cùng một hệ thống. Cách tổ chức này giúp Eurowindow kiểm soát tốt hơn độ chính xác của từng chi tiết, hạn chế sai lệch trong quá trình gia công và đảm bảo sự đồng bộ giữa các sản phẩm kính khi lắp đặt vào công trình.</p><h3>2.2. Hệ thống máy móc nhập khẩu giúp xử lý nhiều yêu cầu kính phức tạp</h3><figure class=\"aluminum-editorial-figure\"><img src=\"/images/vach-kinh-user/kinh-eurowindow-dap-ung-linh-hoat-cac-yeu-cau-cua-moi-hang-muc-cong-trinh.jpg.webp\" alt=\"Kính Eurowindow đáp ứng yêu cầu của các hạng mục công trình\" loading=\"lazy\" decoding=\"async\"></figure><p>Eurowindow sử dụng dây chuyền và thiết bị máy móc nhập khẩu từ các quốc gia có thế mạnh về công nghệ kính như Italia, Phần Lan, Thụy Sĩ và Đức. Hệ thống gồm: máy cắt kính khổ lớn, máy mài song cạnh, máy khoan, máy gia công CNC và lò tôi kính phẳng, cho phép xử lý nhiều dạng kính khác nhau với yêu cầu kỹ thuật cao.</p><p>Nhờ đó, các chi tiết kính được gia công chính xác theo bản vẽ thiết kế, phù hợp với những công trình cần kích thước lớn, hình dạng đặc biệt hoặc yêu cầu lắp ghép phức tạp.</p><h3>2.3. Môi trường sản xuất được kiểm soát nhiệt độ và độ ẩm nghiêm ngặt</h3><figure class=\"aluminum-editorial-figure\"><img src=\"/images/vach-kinh-user/moi-truong-san-xuat-kinh-cua-eurowindow-luon-duoc-kiem-soat-chat-che-nhiet-do-va-do-am.jpg.webp\" alt=\"Môi trường sản xuất kính Eurowindow được kiểm soát nhiệt độ và độ ẩm\" loading=\"lazy\" decoding=\"async\"></figure><p>Các sản phẩm như hộp kính và kính an toàn được gia công trong phòng kín với yêu cầu cụ thể về độ ẩm và nhiệt độ. Việc duy trì môi trường ổn định giúp hạn chế hơi ẩm, bụi bẩn hoặc tạp chất ảnh hưởng đến chất lượng kính, đặc biệt với các sản phẩm có cấu tạo nhiều lớp hoặc cần độ kín khít cao như hộp kính và kính dán an toàn.</p><h3>2.4. Ứng dụng kiểm tra Heat-Soak-Test để sàng lọc kính sau tôi</h3><figure class=\"aluminum-editorial-figure\"><img src=\"/images/product-library/San-pham-kinh/Kinh-an-toan/Kinh-an-toan-05.webp\" alt=\"Ứng dụng kiểm tra Heat-Soak-Test để sàng lọc kính sau tôi – kính Eurowindow\" loading=\"lazy\" decoding=\"async\"></figure><p>Sau quá trình tôi kính, Eurowindow sử dụng thiết bị Heat-Soak-Test để kiểm tra và loại bỏ các tấm kính có nguy cơ lỗi tiềm ẩn. Đây là bước kiểm soát quan trọng trong gia công kính cường lực, giúp phát hiện những sản phẩm không đạt yêu cầu trước khi đưa vào sử dụng thực tế.</p><p>Việc bổ sung công đoạn này cho thấy quy trình sản xuất không chỉ dừng ở gia công tạo hình, mà còn chú trọng kiểm tra chất lượng sau xử lý nhiệt.</p><h3>2.5. Khả năng tôi kính phủ mềm Low-E đòi hỏi kỹ thuật cao</h3><p>Eurowindow ứng dụng công nghệ tôi kính Super Soft Coating Low-E 0,01, một dòng kính phủ mềm có yêu cầu gia công phức tạp hơn kính thông thường. Với loại kính này, lớp phủ cần được bảo vệ trong suốt quá trình cắt, tôi và xử lý bề mặt để không làm ảnh hưởng đến hiệu suất kỹ thuật của kính.</p><p>Khả năng gia công được kính phủ mềm Low-E cho thấy năng lực kiểm soát nhiệt, thiết bị và quy trình sản xuất ở mức cao, phù hợp với các công trình cần giải pháp kính tiết kiệm năng lượng.</p><h3>2.6. Chủ động sản xuất nhiều dòng kính trong cùng một hệ thống</h3><figure class=\"aluminum-editorial-figure\"><img src=\"/images/product-library/San-pham-kinh/Kinh-hoa-van/Kinh-hoa-van-02.webp\" alt=\"Chủ động sản xuất nhiều dòng kính trong cùng một hệ thống – kính Eurowindow\" loading=\"lazy\" decoding=\"async\"></figure><p>Trung tâm kính Eurowindow có khả năng sản xuất đa dạng dòng kính như kính cường lực, kính bán cường lực, kính dán an toàn, hộp kính khổ lớn, kính hoa văn và các loại kính phủ. Việc chủ động nhiều dây chuyền trong cùng một trung tâm giúp Eurowindow đáp ứng linh hoạt các yêu cầu từ cửa, vách ngăn, mặt dựng đến hạng mục trang trí, đồng thời đảm bảo sự đồng bộ về chất lượng và tiến độ cho từng công trình.</p><h2>3. Các dòng sản phẩm kính cao cấp của Eurowindow</h2><p>Eurowindow cung cấp 5 dòng kính chính, mỗi dòng được tối ưu cho một nhóm công năng và vị trí lắp đặt khác nhau.</p><h3>3.1. Kính cường lực và bán cường lực</h3><figure class=\"aluminum-editorial-figure\"><img src=\"/images/eurowindow-products/kinh-cuong-luc-ban-cuong-luc-eurowindow-web.webp\" alt=\"Kính cường lực và bán cường lực – kính Eurowindow\" loading=\"lazy\" decoding=\"async\"></figure><p>Đây là các dòng kính được xử lý nhiệt để tăng khả năng chịu lực, chống va đập, chống rung và chịu sốc nhiệt tốt hơn kính thường.</p><p>Kính cường lực có độ bền gấp 4 - 5 lần kính thường, khi vỡ tạo thành mảnh nhỏ ít sắc cạnh</p><p>Kính bán cường lực có độ cứng gấp 2 - 3 lần, khi vỡ nứt theo đường lượn sóng và vẫn giữ độ dẻo nhất định.</p><p>Nhờ độ an toàn và khả năng chịu lực cao, hai dòng kính này phù hợp cho vách kính lớn, mặt dựng, vách ngăn, cửa thủy lực, lan can, cửa sổ, cửa đi, bàn kính, buồng tắm kính và nhiều hạng mục nội thất.</p><h3>3.2. Kính an toàn</h3><figure class=\"aluminum-editorial-figure\"><img src=\"/images/eurowindow-products/kinh-an-toan-eurowindow.webp\" alt=\"Kính an toàn – kính Eurowindow\" loading=\"lazy\" decoding=\"async\"></figure><p>Kính an toàn Eurowindow là dòng kính dán nhiều lớp, liên kết bằng màng phim PVB giúp tăng độ bền, độ trong suốt và giữ mảnh kính khi xảy ra va đập. Sản phẩm có khả năng chịu lực tốt, hạn chế xâm nhập từ bên ngoài, giảm nguy cơ gây nguy hiểm, đồng thời hỗ trợ cách âm, cách nhiệt và loại trừ phần lớn tia cực tím.</p><p>Kính phù hợp cho cửa sổ, cửa đi tại tòa nhà cao tầng, công trình gần đường lớn, nhà máy, sân bay, phòng thu âm hoặc các khu vực cần tăng độ an toàn và sự yên tĩnh.</p><h3>3.3. Hộp kính và hộp kính khổ lớn</h3><figure class=\"aluminum-editorial-figure\"><img src=\"/images/product-library/San-pham-kinh/Hop-kinh-va-hop-kinh-kho-lon/Hop-kinh-va-hop-kinh-kho-lon-04.webp\" alt=\"Hộp kính và hộp kính khổ lớn – kính Eurowindow\" loading=\"lazy\" decoding=\"async\"></figure><p>Hộp kính Eurowindow là giải pháp kính hiện đại cho cửa sổ, cửa đi, mặt dựng và công trình cao tầng cần diện tích kính lớn. Sản phẩm có kết cấu nhiều lớp với khoảng trống bơm khí Argon và hạt hút ẩm bên trong, giúp tăng khả năng cách âm, cách nhiệt, hạn chế ngưng tụ hơi nước.</p><p>Khi kết hợp với kính dán an toàn hoặc kính cường lực, hộp kính có khả năng chịu va đập tốt, đảm bảo độ chắc chắn, an toàn và mang lại vẻ đẹp hiện đại cho công trình.</p><h3>3.4. Kính cách nhiệt an toàn ACT</h3><figure class=\"aluminum-editorial-figure\"><img src=\"/images/eurowindow-products/kinh-cach-nhiet-an-toan-act-eurowindow.webp\" alt=\"Kính cách nhiệt an toàn ACT – kính Eurowindow\" loading=\"lazy\" decoding=\"async\"></figure><p>Kính cách nhiệt an toàn ACT Eurowindow là dòng kính đơn dán phim cách nhiệt, giúp tăng độ an toàn, giảm nhiệt truyền qua kính và hỗ trợ tiết kiệm điện năng. Sản phẩm giảm tới 57% tổng năng lượng mặt trời, ngăn 75% ánh sáng gây chói và loại bỏ 99% tia cực tím, giúp không gian mát hơn, bảo vệ sức khỏe người dùng và hạn chế phai màu nội thất.</p><p>Khi kính bị va đập, lớp phim giúp giữ lại mảnh vỡ, giảm nguy cơ gây nguy hiểm, phù hợp cho nhà ở, văn phòng và các công trình cần kết hợp cách nhiệt với an toàn lâu dài.</p></article></div></section>";
    return productGuideLayout(content.title,content.points,content.applications,productCatalogRows(slug),[content.intro,content.body]);
  }
  function productPageFaq(content,slug){
    if(slug==='cua-upvc')return [
      ['Cửa uPVC Eurowindow có khả năng cách âm, cách nhiệt không?','Cấu tạo profile dạng hộp, lõi thép gia cường, gioăng kép và hộp kính bơm khí trơ hạn chế truyền âm, truyền nhiệt. Cửa uPVC Eurowindow có khả năng cách nhiệt cao gấp 2–4 lần so với các loại cửa thông thường.'],
      ['Cửa uPVC Eurowindow gồm những bộ phận nào?','Bộ cửa gồm thanh profile uPVC dạng hộp có lõi thép gia cường, hộp kính, gioăng kép và hệ phụ kiện đồng bộ với chốt đa điểm, bản lề 3D, khóa chuyên dụng.'],
      ['Cửa uPVC Eurowindow có những kiểu mở nào?','Danh mục gồm cửa mở quay vào trong, mở quay ra ngoài, mở hất, mở quay lật, mở trượt và mở song song.']
    ];
    if(slug==='cua-go')return [
      ['Cửa gỗ Eurowindow có những dòng nào?','Danh mục gồm cửa gỗ tự nhiên, cửa gỗ công nghiệp, cửa gỗ ghép thanh, cửa gỗ composite và cửa gỗ chống cháy.'],
      ['Cửa gỗ composite phù hợp với vị trí nào?','Cửa gỗ composite có khả năng kháng nước cao, phù hợp với phòng tắm, nhà vệ sinh và khu vực có độ ẩm cao.'],
      ['Cửa gỗ có những bề mặt hoàn thiện nào?','Các bề mặt gồm sơn PU, veneer gỗ tự nhiên, laminate, melamine, film vân gỗ và lớp phủ chuyên dụng.']
    ];
    if(slug==='cua-thong-minh-the-he-moi')return [
      ['Cửa thông minh Eurowindow gồm những sản phẩm nào?','Danh mục gồm cửa trượt Slim ray treo, rèm trong hộp kính, kính điện đổi màu, cửa bản lề sàn tự động, cửa gấp trượt dọc, cửa sổ điều khiển giọng nói, vách trượt dọc, cửa lưới chống muỗi, cửa sổ đẩy ngang, cửa trượt tự động, cửa mái kính Skylight và cửa sổ tự động.'],
      ['Cửa thông minh được điều khiển bằng cách nào?','Các dòng sản phẩm sử dụng ứng dụng điện thoại, remote, nút bấm gắn tường hoặc giọng nói theo chức năng của từng sản phẩm.'],
      ['Cửa thông minh có những cảm biến an toàn nào?','Các giải pháp gồm cảm biến va chạm, cảm biến lực, cảm biến mưa, gió, cảm biến báo khói và cảm biến chống kẹp tay theo từng dòng sản phẩm.']
    ];
    return content.faq;
  }
  function officialProductPage(slug){
    const content=productPageContent[slug];
    const rows=productCatalogRows(slug);
    const uniqueImageRows=[...new Map(rows.filter(([,image])=>image).map(row=>[row[1],row])).values()];
    const galleryRows=uniqueImageRows.length>3?uniqueImageRows.slice(0,7):rows.slice(0,3);
    const gallery=galleryRows.map(([name,image,type,opening])=>({name,image:productCatalogImage(image),caption:type+' · '+opening}));
    if(gallery.length<3){
      categories.filter(item=>item.slug!==slug).slice(0,3-gallery.length).forEach((item,index)=>gallery.push({name:content.title,image:img(item.image,1400),caption:'Ứng dụng · '+content.title+' '+(index+1)}));
    }
    let pageHtml=`${compactProductHero(content.title)}<section class="section"><div class="wrap detail-grid"><div class="detail-gallery" data-gallery><div class="gallery-stage">${gallery.map((item,i)=>`<button type="button" class="gallery-slide ${i===0?'active':''}" data-gallery-slide="${i}" aria-label="Xem ${item.name}, ảnh ${i+1}"><img loading="lazy" alt="${item.name}" src="${item.image}"><span class="gallery-caption">${item.caption} · ${String(i+1).padStart(2,'0')} / ${String(gallery.length).padStart(2,'0')}</span></button>`).join('')}</div><div class="gallery-controls"><button type="button" data-gallery-prev aria-label="Ảnh trước">&larr;</button><span class="gallery-counter" data-gallery-counter>01 / ${String(gallery.length).padStart(2,'0')}</span><button type="button" data-gallery-next aria-label="Ảnh tiếp theo">&rarr;</button></div></div><div class="detail-info"><span class="detail-label">${content.label}</span><h2>${content.title}</h2><div class="detail-copy"><p>${content.intro}</p><p>${content.body}</p></div><a class="button" href="/bao-gia?san-pham=${encodeURIComponent(content.title)}">Nhận tư vấn và báo giá <span class="arrow">&nearr;</span></a></div></div></section>${productGuideSections(content,slug)}<section class="section aluminum-pricing"><div class="wrap"><div class="section-head"><div><span class="eyebrow">TƯ VẤN CHI PHÍ</span><h2 class="serif">Báo giá ${displayProductName(content.title)}</h2></div><p>Giá bán thay đổi tùy dòng sản phẩm và thời điểm.</p></div><p class="detail-copy">Liên hệ Eurowindow để nhận thông tin giá bán và ưu đãi mới nhất cho sản phẩm này.</p><a class="button" href="/bao-gia?san-pham=${encodeURIComponent(content.title)}">Yêu cầu báo giá <span class="arrow">&nearr;</span></a></div></section><section class="section aluminum-faq"><div class="wrap"><div class="section-head"><div><span class="eyebrow">CÂU HỎI THƯỜNG GẶP</span><h2 class="serif">Giải đáp về ${displayProductName(content.title)}</h2></div></div><div class="aluminum-faq-list">${productPageFaq(content,slug).map(([question,answer])=>`<article class="aluminum-faq-item"><h3>${question}</h3><p>${answer}</p></article>`).join('')}</div></div></section><section class="quote-band"><div class="wrap quote-grid"><div><span class="eyebrow">TƯ VẤN SẢN PHẨM</span><h2 class="serif">Chọn Cửa phù hợp<br><span class="gold">với công trình của bạn</span></h2><p>Liên hệ với Eurowindow để được giới thiệu mẫu mã và dòng sản phẩm phù hợp.</p></div>${productInquiryForm([content.title])}</div></section>`;
    return ['cua-go','cua-upvc','cua-thong-minh-the-he-moi','vach-kinh-mat-dung'].includes(slug)?pageHtml.replace(/<section class="section aluminum-pricing">[\s\S]*?<\/section>/,'').replace(/<section class="section aluminum-faq">[\s\S]*?<\/section>/,''):pageHtml;
  }
  const productListingCopy={
    'cua-nhom':'Cửa đi, cửa sổ và vách nhôm kính. Chọn kiểu mở, kính và hệ nhôm theo vị trí lắp đặt.',
    'cua-upvc':'Cửa đi và cửa sổ uPVC thuộc các dòng Asiawindow và Kömmerling. Lựa chọn kính và phụ kiện cần xác nhận theo từng mẫu.',
    'cua-go':'Cửa gỗ tự nhiên, gỗ công nghiệp, gỗ ghép thanh và composite. Chọn bề mặt theo nội thất và vị trí sử dụng.',
    'cua-cuon':'Cửa cuốn nhôm khe thoáng EASD45 có nan mành thông thoáng, điều khiển mã số trượt và cảm biến an toàn. Phù hợp nhà phố, cửa hàng, gara và công trình thương mại.',
    'cua-thong-minh-the-he-moi':'Cửa thông minh Eurowindow gồm cửa tự động, cửa sổ điều khiển bằng giọng nói, kính điện đổi màu và giải pháp kết nối Smarthome.',
    'vach-kinh-mat-dung':'Kính và vách kính cho cửa, vách ngăn và mặt dựng. Chọn cấu tạo theo vị trí và yêu cầu của công trình.'
  };
  function officialProductListingPage(){
    const qs=new URLSearchParams(location.search).get('danh-muc');
    const shown=(qs?categories.filter(item=>item.slug===qs):categories);
    return `${compactProductHero('Cửa, kính và vách kính')}<section class="section"><div class="wrap"><div class="listing-tools product-listing-tools"><div class="filters" id="productFilters"><button class="filter ${qs?'':'active'}" data-cat="all">Tất cả</button>${categories.map(item=>`<button class="filter ${qs===item.slug?'active':''}" data-cat="${item.slug}">${item.name}</button>`).join('')}</div></div><div class="product-grid" id="productGrid">${shown.map(item=>productCard({...item,desc:productListingCopy[item.slug]||item.desc})).join('')}</div></div></section><section class="quote-band"><div class="wrap quote-grid"><div><span class="eyebrow">TƯ VẤN SẢN PHẨM</span><h2 class="serif">Tìm Cửa phù hợp<br><span class="gold">với công trình của bạn</span></h2><p>Chia sẻ loại cửa đang tìm và nhu cầu sử dụng để bắt đầu trao đổi.</p></div>${productInquiryForm(categories.map(item=>item.name))}</div></section>`;
  }
  function wireProductListingImages(){
    const grid=document.querySelector('#productGrid');
    if(!grid)return;
    grid.querySelectorAll('.product-card').forEach(card=>{
      const photo=card.querySelector('.product-photo'),image=photo?.querySelector('img');
      if(!photo||!image||photo.dataset.featureImageReady)return;
      const slug=card.getAttribute('href')?.split('/').filter(Boolean).pop();
      const rows=productCatalogRows(slug);
      const fallback=rows.find(([,path])=>path)||[];
      const featured=window.__EUROWINDOW_PRODUCT_CATEGORY_IMAGES__?.[slug];
      const name=featured?.alt||fallback[0],src=featured?.src||fallback[1];
      if(!src)return;
      image.src=src.startsWith('/')||src.startsWith('http')?src:productCatalogImage(src);
      image.alt=name||'Sản phẩm Eurowindow';
      photo.dataset.featureImageReady='true';
    });
  }
